quests[57088] = { id = 57088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht meins", description = "Sylvanas' Loyalisten haben einen Teil des Pfads durch die Schlucht nach Orgrimmar zum Einsturz gebracht. Unsere Truppen wurden getrennt.\n\nWir müssen unserer Frontlinie verstärken oder die Banshee wird uns nach Belieben ausschalten. Wir sind zu weit gekommen, um einen Tod auf Raten zu sterben.\n\nGazlowe und ein Gnom der Allianz glauben, die Antwort zu haben. Ihr stellt besser sicher, dass ihr Plan nicht nach hinten losgeht.", sourceObjective = "Beseitigt Felsen, Minen und andere Hindernisse aus dem Pass zwischen Klingenhügel und Orgrimmar.", completion = "Die schnelle Reaktion hat unseren Soldaten das Leben gerettet, aber es gibt noch mehr zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[57089] = { id = 57089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutstätte der Vil'thik" }
quests[57090] = { id = 57090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung der Belagerung", description = "Im Chaos der Felsstürze haben es die Spione der Banshee geschafft, unsere Wachen zu umgehen. Sie haben Bomben an unseren Belagerungswaffen angebracht.\n\nEntfernt diese Bomben.", sourceObjective = "Entfernt 8 verdächtige Kisten.", completion = "Gute Arbeit. Wir können nicht noch mehr Waffen an Sylvanas' Verrat verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[57091] = { id = 57091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bereits unter uns", description = "Sylvanas hat immer noch viele treue Gefolgsleute in der Horde. Der Krieg, den sie heraufbeschworen hat, hat viele vor Hass und Wut blind werden lassen. Das nutzt sie für ihre Zwecke aus.\n\n<Saurfang blickt finster.>\n\nSie können nicht sehen, dass sie uns in den Untergang führen wird und dass ihre sogenannten Siege hohle Lügen sind.\n\nEinige ihrer Agenten wurden in unseren Reihen entdeckt. Tötet sie. Sie werden uns keine Gnade erweisen, und wir ihnen auch nicht.", sourceObjective = "Tötet 10 verdächtige Techniker und Assassinen der Loyalisten.", completion = "Beide haben wir Blut an unseren Händen. Heute sorgen wir dafür, dass das nicht umsonst war.", sourceObjectiveStatus = "unverified-source-field" }
quests[57092] = { id = 57092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strategischer Einsatz", description = "Ich habe über Jahre die Tore von Orgrimmar geschützt. Die vielen Zugänge waren schon immer der größte Schwachpunkt der Stadt. Wir sollten sie alle gleichzeitig angreifen, um uns den Sieg zu sichern.\n\nWrynn und ich haben die Einsatzbefehle zusammengestellt. Die Magier werden unsere Flanke decken. Graumähne wird von Westen kommen und die Elfen nehmen den Norden. Mayla wird die Verteidigung in Donnerfels stärken, falls Sylvanas einen Gegenangriff startet.\n\nBringt die Befehle zu den Kommandanten.", sourceObjective = "Überbringt Saurfangs Einsatzbefehle.", completion = "Welcher Strategie wir auch immer folgen, Orgrimmar einzunehmen wird keine leichte Aufgabe. Ich sollte es schließlich wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57093] = { id = 57093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren von Orgrimmar", description = "Es ist Zeit.\n\nWir haben uns so gut es geht vorbereitet. Jetzt fehlt nur noch die eigentliche Schlacht.\n\nIch bin kein Freund von Reden, also nur Folgendes:\n\nLok-tar ogar, {name}. Sieg. Oder Tod.", sourceObjective = "Beginnt die Schlacht vor den Toren Orgrimmars.", completion = "Saurfang... von dunkler Magie getötet...\n\nIn all den Jahren, die ich Sylvanas jetzt kenne, hat sie noch nie solche Macht demonstriert. Warum zeigt sie uns das jetzt? Was bringt es ihr, die Horde aufzugeben?\n\n<Lor'themars Auge verengt sich zu einem Schlitz.>\n\nWas auch immer sie plant, es sieht so aus, als ob sie die Horde nicht mehr braucht, um ihr Ziel zu erreichen. Wir müssen vorsichtig sein, {name}. Wir können ihren nächsten Zug unmöglich vorausahnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57094] = { id = 57094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Preis des Sieges", description = "Saurfang... ich...\n\n<Lor'themar nimmt sich einen Moment, um sich zu sammeln.>\n\n...Thrall wird das Opfer von Saurfang ehren wollen, genau wie der Rest von uns.\n\nRuft unsere Truppen zusammen. Erzählt ihnen, was passiert ist. Erzählt ihnen, dass unser großer Krieger Varok Saurfang tot ist und der Kriegshäuptling uns verlassen hat.\n\nSprecht mit Baine, wenn Ihr in Donnerfels ankommt. Ihr findet ihn auf der Anhöhe der Ältesten. Ich bin mir sicher, er wird Saurfang auch die Ehre erweisen wollen. \n\nLasst uns einmal mehr als vereinte Horde zusammenstehen.", sourceObjective = "Informiert Baine Bluthuf darüber, was geschehen ist.", completion = "Saurfangs Tod wird nicht vergebens sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[57095] = { id = 57095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alter Soldat", description = "Egal, was manche sagen mögen. Er war ein ehrenvoller Orc. Ein Legende. Er war das Ideal, zu dem alle Krieger der Horde aufgesehen haben. \n\nEr hat sein Leben geopfert, um die Kluft in der Horde zu versiegeln, und uns die Chance gegeben, einen neuen Weg einzuschlagen. Sein Tod war mehr als nur der Tod eines Kriegers. Es war der Tod eines Helden.\n\nWir müssen sein Opfer ehren.", sourceObjective = "Ehrt Hochfürst Saurfang.", completion = "Wir werden ihn in Nagrand begraben, wie er es gewollt hätte.\n\nDie Zukunft der Horde kann ich nicht vorhersagen, aber ich weiß, dass wir ihr gemeinsam entgegentreten werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[57098] = { id = 57098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hain des Schreckens", description = "Ah, ja. Ihr habt mir einen großen Gefallen damit getan, die Anklägerin auszuliefern, <Schlundgänger/Schlundgängerin>.\n\nUm das zu feiern, muss ich darauf bestehen, dass Ihr an einer heiligen Tradition Revendreths teilnehmt: der Büßerjagd. Es ist unsere Pflicht, die Herzen der... störrischsten Seelen... mit demütigender Furcht zu erfüllen.\n\nFurcht kann eine sehr motivierende Kraft der Veränderung sein.\n\nTrefft die Furchthetzerin unten im Hain des Schreckens. Ihr werdet Euch dort vorbereiten.", sourceObjective = "Trefft Euch mit der Furchthetzerin im Hain des Schreckens.", completion = "Willkommen im Hain des Schreckens.\n\nHier werdet Ihr miterleben, wie die Form von Anima entsteht, nach der Ihr sucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[57099] = { id = 57099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dreadful Roundup" }
quests[57100] = { id = 57100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeding Time is Over" }
quests[57101] = { id = 57101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlangenkäfig der Zan-Tien" }
quests[57102] = { id = 57102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn doch der Staub nicht wäre", description = "Ah, ja, der Begrüßer.\n\nDiese Mnemiseinheit scheint deaktiviert worden zu sein. Es gibt so wenig Anima in letzter Zeit, und ohne neue Seelen an unseren Toren war es wohl eine umsichtige Maßnahme. Anima ist schließlich unsere wertvollste Ressource.\n\nEs sind ein paar Zenturionen in der Nähe. Ein Teil ihrer Anima könnte für unsere Zwecke eingesetzt werden.\n\nAh! Eine unserer hilfsbereitesten Provostinnen ist hier, um zu helfen. Sie wird Euch beim Sammeln anleiten.\n\nKehrt zurück, wenn Ihr genug Anima gesammelt habt. Dann werden wir den Begrüßer wieder aktivieren.", sourceObjective = "Sammelt Anima von Zenturionen in der Nähe.", progress = "<Der Zenturio reagiert nicht.>", completion = "<Der Zenturio gibt ein sanftes Läuten von sich.>", sourceObjectiveStatus = "unverified-source-field" }
quests[57103] = { id = 57103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufwertung für Euer Fahrzeug (optional)" }
quests[57104] = { id = 57104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expeditionsmikrojetpack GG-118" }
quests[57105] = { id = 57105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufwertung für Euer Jetpack (optional)" }
