quests[57107] = { id = 57107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufwertung für Euren A.T.O.M.I.K. Mk. II (optional)" }
quests[57113] = { id = 57113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lysonia auf der Spur", description = "Unsere Späher haben berichtet, dass Lysonia und Uther unterwegs zum Tempel der Demut sind.\n\nDa sie nach Lage der Dinge die Anführerin der Verschmähten ist, dürfen wir ihr nicht freie Hand lassen, allen um sich herum die Köpfe zu verdrehen.\n\nDie Jünger der Demut haben unsere Rufe unbeantwortet gelassen. Ich habe Kleia als Kundschafterin vorausgeschickt. Trefft sie vor dem Tempel.", sourceObjective = "Trefft Euch mit Kleia vor dem Tempel der Demut.", completion = "Der ganze Tempel ist von Verschmähten überrannt. Wir müssen die Überlebenden finden!", sourceObjectiveStatus = "unverified-source-field" }
quests[57114] = { id = 57114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luftaufklärung", description = "Das Tempelgelände wimmelt nur so vor denen, die den Verschmähten treu ergeben sind.\n\nWäre ich immer noch Aspirantin, wäre diese Aufgabe gewaltig. Glücklicherweise ist das nicht länger der Fall.\n\nSehen wir uns die Lage vom Himmel aus an. Wir beide können die Herausforderungen, die uns bevorstehen, abschätzen und so viele Überlebende wie möglich finden.", sourceObjective = "Fliegt mit Kleia, um die Überlebenden zu finden.", completion = "Zum Glück habt Ihr beide uns gefunden.\n\nWir haben eine Menge Verwundete. Ich konnte sie am Leben halten, doch das hat meine gesamte Konzentration erfordert. Ihr müsst uns helfen, die Verschmähten zurückzudrängen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57115] = { id = 57115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilige Schriftrollen der Demut", description = "Die Verschmähten plündern die Bibliothek und suchen in unseren Archiven nach bestimmten Texten.\n\nWir dürfen nicht zulassen, dass sie die Schriftrollen entdecken, nach denen sie suchen. Findet alle Schriftrollen, die beiseitegelegt wurden, und bringt sie mir zur Aufbewahrung.", sourceObjective = "Sammelt 5 heilige Schriftrollen.", progress = "Die Schriftrollen in diesen Tempeln behandeln viele Themen, von Informationen zu fremden Welten über die Säulen der Ausbildung bis hin zu uralten Ritualen.", completion = "Offenbar sammeln sie Informationen darüber, wie man eins unserer stärksten Rituale durchführt. Aber zu welchem Zweck?", sourceObjectiveStatus = "unverified-source-field" }
quests[57116] = { id = 57116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Stolz ergeben", description = "Die Aspiranten, die die meiste Zeit in diesem Tempel verbringen, sind diejenigen, die sich ihrem Stolz stellen müssen.\n\nIch war einst eine von ihnen.\n\nWährend unserer Überwachung habe ich gesehen, wie Verschmähte diese Aspiranten dazu getrieben haben, ihren Lastern zu verfallen, nur um sie dann fallen zu lassen, als wären sie nichts wert.\n\nIhr müsst die Verschmähten aufhalten. Befreit die Aspiranten von einem furchtbaren Schicksal.", sourceObjective = "Befreit 5 belastete Aspiranten, indem Ihr die Rituale der Verschmähten unterbindet.", completion = "Danke, {name}. Diese Aspiranten werden weiterleben, um sich zu bessern und der Bastion zu dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57117] = { id = 57117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihren Lastern verfallen", description = "Lysonias Streitkräfte plündern unseren heiligen Tempel... Den Armen der Archon sind sie schon lange entglitten.\n\nEs schmerzt mich, aber Ihr müsst sie bezwingen, damit sie unser Volk nicht mehr peinigen können.\n\nNehmt Mitgefühl mit Euch. Die Klinge wird nützlich sein, jetzt, da sie ihre Macht zurückerlangt hat.", sourceObjective = "Bezwingt 15 Streitkräfte der Verschmähten auf der Terrasse der Inneren Anmut.", completion = "Die Verschmähten zu bekämpfen, unsere Brüder und Schwestern... es wird nie einfacher.", sourceObjectiveStatus = "unverified-source-field" }
quests[57118] = { id = 57118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Schlund verzerrt", description = "Lysonias Streitkräfte leiten die Animasammler um, damit sie Schlundenergie in den Tempel pumpen. Sie hemmen unsere Kräfte und stärken ihre eigenen.\n\nDie Sammler wurden verderbt. Nehmt Mitgefühl und und zerstört sie, um Lysonias Gabe zu stoppen.", sourceObjective = "Zerstört 3 Animasammler auf der Terrasse der Inneren Anmut.", completion = "Sorgt Euch nicht um die Sammler. Durch die Dürre sind sie schon seit einiger Zeit kaum noch funktionsfähig.", sourceObjectiveStatus = "unverified-source-field" }
quests[57120] = { id = 57120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitgefühl, Klinge der Demut", description = "<Ihr findet ein vertraut aussehendes Schwert in einer Leiche der Verschmähten stecken. Das Paragon der Demut muss es bei der Verfolgung von Lysonia zurückgelassen haben.\n\nEs wirkt inaktiv, als ob all seine Anima aufgebraucht wäre. Vielleicht könntet Ihr es zu seiner gewohnten Pracht wiederherstellen.>", sourceObjective = "Ladet Mitgefühl, Klinge der Demut, auf, indem Ihr Manifestationen tötet.", completion = "Mitgefühl!\n\nDas Paragon hat Lysonia in solcher Eile verfolgt, dass es sein Schwert zurückgelassen hat. Das könnte die Chance sein, die Verschmähten aus dem Tempel zu vertreiben.\n\nNehmt es mit Euch... und möge es Euch gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[57121] = { id = 57121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Schlunds", description = "Lysonia flieht in den Schlund, um ihre dunklen Rituale durchzuführen. Nur Ihr als <Schlundgänger/Schlundgängerin> könnt sie verfolgen.\n\nNehmt Kleia und meine Klinge mit. Sie muss aufgehalten werden.", sourceObjective = "Betretet den Schlund mit Kleia und trefft sie dann vor der Verdammnisfestung.", completion = "Ich spüre die Unterdrückung hier wie eine echte Last auf meinem Körper.", sourceObjectiveStatus = "unverified-source-field" }
quests[57122] = { id = 57122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Schritt zu weit", description = "Meine erste Spähmission hat Dinge enthüllt, die ich anfangs nicht glauben wollte.\n\nDie Schlundgebundenen halten Verschmähte hier gefangen und verwandeln sie gegen ihren Willen.\n\nObwohl die Verschmähten sich gegen die Archon gestellt haben, sind sie immer noch Kyrianer. Es ist unsere Pflicht, sie zu befreien.", sourceObjective = "Befreit 5 gefangene Verschmähte.", completion = "Von der Archon verbannt... Von Lysonia im Stich gelassen...\n\nWo sollen sie hin?", sourceObjectiveStatus = "unverified-source-field" }
quests[57123] = { id = 57123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht länger Kyrianer", description = "Schlundgebundene Kyrianer... Ich habe seit der Vision bei unserer ersten Begegnung keinen von ihnen mehr gesehen.\n\nIch bin nicht eingeschüchtert. Sie sind Feinde der Bastion und der Archon. Es ist unsere Pflicht, sie zu besiegen.", sourceObjective = "Tötet 15 Streitkräfte der Schlundgebundenen.", completion = "Sollte mein Verstand je durch den Schlund entstellt werden... dann bitte ich Euch, mir ein Ende zu setzen.\n\nIch kann den Gedanken nicht ertragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57124] = { id = 57124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr aufgezwungener Wille", description = "Ich spüre, wie es mich über die Zwillingsbrücken im Westen zieht...\n\nLysonia muss dort sein.\n\nKommt, {name}. Wir müssen sie stellen, bevor sie erneut entkommen kann. Wer weiß, was sie vorhat.", sourceObjective = "Stellt Lysonia am Altar der Herrschaft.", completion = "Es scheint, dass... ich der Dummkopf bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[57125] = { id = 57125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit der Reflexion", description = "Ich wusste, dass Devos mächtige Verbündete hat. Ich habe die Augen davor verschlossen. Als Lysonia ihren Platz einnahm... ließ ich mich durch meine Loyalität blenden.\n\nIch muss über so vieles nachdenken.\n\nWir mögen keine Verbündeten sein, aber ich habe eine Bitte. Seid so gut, mich aus diesem elenden Ort hinauszubegleiten. Ich werde Euch in Ruhe lassen... aber lasst mich nicht hier im Schlund.", sourceObjective = "Sprecht mit Kleia, um den Schlund zu verlassen, und kehrt dann zu Polemarch Adrestes in die Elysische Feste zurück.", completion = "Ein Jammer, dass Lysonia uns wieder einmal entkommen ist... Ihr nun enthüllter Meister und ihre neuen Kräfte bereiten mir Sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57126] = { id = 57126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glück und Segen...", description = "Mein Bruder Derek ist im Zweiten Krieg gestorben, nur um dann von der Bansheekönigin gegen seinen Willen wiedererweckt zu werden. Hätte sich Baine Bluthuf dem nicht mutig entgegengestellt, wäre Derek zur Waffe gegen meine Familie geworden.\n\nSeit seiner Wiedererweckung war sein Dasein eine Qual. Ich hatte schon gedacht, dass wir ihn verloren hätten, aber eine alte Freundin, die ebenfalls wiedererweckt wurde, hat ihm geholfen. Das war Calia Menethil. Sie hat ihm einen Weg heraus aus der Verzweiflung gezeigt.\n\nIch bin gerade auf dem Weg, sie zu besuchen. Möchtet Ihr Euch anschließen?", sourceObjective = "Besucht Derek Prachtmeer und Calia Menethil.", completion = "Willkommen. Es ist schön, Gesellschaft zu haben.\n\nAh, Jaina ist angekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57129] = { id = 57129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Tal der Weisheit" }
quests[57130] = { id = 57130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verräter unter uns", description = "Es gibt einen Unterschied zwischen Loyalität und blindem Gehorsam. Den Befehlen der Banshee folge ich nie wieder!", sourceObjective = "Kümmert Euch um diesen Verräter.", completion = "Der Kriegshäuptling hatte lange den Verdacht, dass dieser Verräter nicht den Mut hat zu tun, was nötig ist.\n\nIhr andererseits... Ihr versteht.", sourceObjectiveStatus = "unverified-source-field" }
quests[57131] = { id = 57131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst die Jagd beginnen", description = "Es bleibt nur noch eins zu tun, bevor die Büßerjagd beginnen kann.\n\nIhr und die anderen Jäger werdet den Seelen zunächst ein wenig Anima entziehen. Das wird ein Leichtes sein. Die Zeit der Seele im Hain des Schreckens setzt Animaspuren frei.\n\nDiese Anima hilft uns Venthyr, die Beute anhand ihrer Angst zu verfolgen.\n\nAußerdem bitte ich Euch, uns die Ehre zu erweisen und das Signal für die Jagd zu geben.\n\n<Die Furchthetzerin gibt Euch einen Animapflock und einen ausgehöhlten Fleddermauszahn.>\n\nVerwendet das, um die Aufgabe auszuführen.", sourceObjective = "Schließt das Jagdritual auf dem Schwundgrufthügel ab.", progress = "Die Zeremonie muss weitergehen.", completion = "Gut gemacht. Vielleicht wird ja im Tod noch ein guter Jäger aus Euch.\n\nIch kann bereits die Angst schmecken, die wir ihnen einjagen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[57136] = { id = 57136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Büßerjagd", description = "Ihr werdet Jagd auf diese armen Seelen machen. Vergesst nicht, dass Ihr ihnen und Revendreth mit dem Entsetzen, das Ihr in ihnen weckt, letzten Endes helft. Wenn eine Seele von Furcht erfüllt ist, schwindet ihr Widerstand gegen unsere Methoden.\n\nDer Meister wünscht, dass Ihr die Anklägerin persönlich jagt, doch zunächst müssen wir einigen der anderen nachstellen.\n\nIch werde Euch durch Eure erste Jagd führen.", sourceObjective = "Sprecht mit der Furchthetzerin auf dem Schwundgrufthügel und nehmt an der Büßerjagd teil.", progress = "Die Seelen müssen gejagt werden.", completion = "Gut gemacht. Durch die Angst, die wir verbreitet haben, konnten wir reichlich Anima für Revendreth extrahieren.\n\nAuf zu unserem letzten Ziel.", sourceObjectiveStatus = "unverified-source-field" }
quests[57146] = { id = 57146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbnisriss" }
quests[57147] = { id = 57147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht mein Kriegshäuptling", description = "Es bleibt nicht viel Zeit. Sylvanas weiß, was ich vorhabe und hat daher Euch geschickt, um mich zu töten. Ich bezweifle, dass Eure Entscheidung ihr gefallen wird.\n\nWir müssen schnell zu den Wyvern und uns in die Lüfte erheben.", sourceObjective = "Flieht mit Etrigg und trefft Euch mit Saurfang in Klingenhügel.", completion = "Etrigg hat mir erzählt, dass Ihr aus Orgrimmar entkommen seid. Es gibt sicherlich noch andere Dissidenten in der Stadt, die das nicht geschafft haben.\n\nDas einzige, was wir jetzt tun können, ist diese Schlacht zu beenden, bevor Sylvanas sie leiden lässt.", sourceObjectiveStatus = "unverified-source-field" }
quests[57148] = { id = 57148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagerungsbrecher", description = "Die Narren, die sich Saurfang angeschlossen haben, fühlen sich mutig genug, einen Frontalangriff zu wagen. Wir dürfen diesem Gewürm nicht erlauben, sich vor unseren Toren zu formieren.\n\nIn diesem Moment bringen unsere Agenten den Pass zwischen Klingenhügel und Orgrimmar zum Einsturz und schneiden Saurfangs Rotte von Verrätern in zwei Hälften.\n\nEure Aufgabe ist es, Euch unter sie zu mischen und ihre Belagerungswaffen zu sabotieren. Legt diese Verkleidung an, aber seid vorsichtig: Sie hält einer näheren Untersuchung nicht stand. Tötet jeden, der droht, Euch zu entlarven.", sourceObjective = "Platziert heimlich verdächtige Kisten und tötet Wachen.", completion = "Sie tun mir leid. Diese Narren.\n\n<Nathanos grinst.>", sourceObjectiveStatus = "unverified-source-field" }
quests[57149] = { id = 57149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Propagandakontrolle", description = "Einige Widerständler verteilen Propaganda in der Stadt und verbreiten dreiste Lügen.\n\nWir dürfen uns keine Illusionen machen: Eine Armee von Verrätern und unseren Erzfeinden versammelt sich vor unseren Toren. Wenn es nach diesen Narren geht, würden wir von den Pfeilen der Allianz durchbohrt.\n\n<Nathanos rollt die Augen.>\n\nReißt diesen Mist herunter. Das kann nur Panik auslösen.\n\nUnd solltet Ihr dabei auf... Widerstand stoßen... Ihr seid hiermit bemächtigt, Gewalt einzusetzen.", sourceObjective = "Verbrennt die Propaganda der Widerständler in Orgrimmar.", completion = "Gut gemacht. Ich nehme an, Ihr seid nicht auf viel Widerstand getroffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57150] = { id = 57150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Miliz", description = "Wir haben einen hohen Blutzoll in diesem Krieg gezahlt, unsere Reihen sind gelichtet. Aber die Horde ist immer noch stark. Jeder Bürger von Orgrimmar ist auf dem Schlachtfeld zehn Allianzschwächlinge wert.\n\nRuft die Bürger zusammen und formt eine Miliz! Erinnert sie an ihre getöteten Brüder und Schwestern!", sourceObjective = "Versammelt die Bewohner von Orgrimmar.", completion = "Unsere Streitkräfte werden immer stärker, während die unserer Feinde stetig schwinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[57151] = { id = 57151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Linie im Sand", description = "In der Stadt haben wir aufgeräumt, jetzt ist es Zeit, den Dreck vor unseren Toren zu tilgen.\n\nWie praktisch, dass diese Verräter sich alle zusammen eingefunden haben, damit wir sie mit einem Schlag auslöschen können.\n\nSetzen wir dieser erbärmlichen Rebellion ein Ende.", sourceObjective = "Sprecht mit Nathanos.", completion = "Ich habe Befehle der Dunklen Fürstin für Euch. Sie hat mich angewiesen, sie an ihrer Stelle zu überreichen, wenn die Lage es erfordert.", sourceObjectiveStatus = "unverified-source-field" }
quests[57152] = { id = 57152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treu ergeben", description = "Die Dunkle Fürstin hat diesen Ausgang vorhergesehen und dafür einen Notfallplan vorbereitet.\n\nSie will, dass Ihr Euch in die Geisterlande begebt. Benutzt diesen Ruhestein. Er hat noch genug Energie für eine Reise.\n\nSie wird Euch in der Nähe des Windläuferturms treffen.", sourceObjective = "Sprecht mit Sylvanas Windläufer.", completion = "Man wird sich an Euch für Euren loyalen Dienst erinnern.", sourceObjectiveStatus = "unverified-source-field" }
quests[57153] = { id = 57153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zwergendistrikt" }
quests[57155] = { id = 57155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge blenden", description = "Ah, ja, auf Euch habe ich gewartet, {class}.\n\nIch spüre immer noch seinen Hauch auf Euch. Euer Sieg über den Gott der Tiefe wird nicht endgültig sein, ehe wir nicht alle Spuren seiner Infektion entfernt haben.\n\nDurch meine Forschungen habe ich einen weniger schmerzvollen Weg gefunden, die Infektion zu beseitigen.\n\nSprecht mich an, dann werden wir diesem Alptraum ein Ende bereiten.", sourceObjective = "Sprecht mit Bruder Pike, um Eure \"Gabe\" zu bereinigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57156] = { id = 57156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge blenden", description = "Da seid Ihr ja endlich, {name}. Euer finstres Mojo is' schon zu lange da. N'Zoth is' besiegt un' wir müss'n alle Spur'n der Infektion von Euch beseitigen.\n\nTut auch nich' weh. Nich' doll.\n\nSagt mir, wenn Ihr soweit seid.", sourceObjective = "Sprecht mit Nailok, um Eure \"Gabe\" zu bereinigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57157] = { id = 57157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff: Das Schwarze Imperium", description = "Es ist genau so, wie es in den Visionen vorhergesagt wurde. Finstere Streitkräfte sind gekommen, um die Schmiede des Ursprungs zu beanspruchen.\n\nSie müssen aufgehalten werden oder ganz Azeroth wird sein Ende finden!", sourceObjective = "Schlagt den Angriff von N'Zoth in Uldum zurück.", progress = "Dieser Wahnsinn... Er verschlingt alles!", completion = "Die Stimmen sind verstummt. Die Visionen zeigen mir den Tagesanbruch.\n\nWir werden diesen Tag überleben, dank Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[57158] = { id = 57158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elektrische Ermächtigung" }
quests[57159] = { id = 57159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Reflexion der Wahrheit", description = "Ich habe die Furchthetzerin mit der Falle weit weg von hier geschickt und uns etwas Zeit verschafft.\n\nAuf der anderen Seite dieses Spiegels liegen die Tiefen von Schloss Nathria, der Festung von Denathrius höchstpersönlich. An diesem Ort wird ein Treffen zwischen Denathrius und einem seiner Schergen stattfinden.\n\nFolgt mir durch den Spiegel, {name}, und Ihr werdet die Wahrheit hinter dieser \"Dürre\" mit eigenen Augen erblicken.", sourceObjective = "Folgt der Anklägerin durch den Spiegel und erfahrt die Wahrheit über Revendreth.", completion = "Wir haben es gerade noch geschafft. Denathrius wird uns sicher bald auf der Spur sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[57161] = { id = 57161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich mache mir nicht die Hände schmutzig", description = "Ihr habt Graf Denathrius gehört. Heute steige ich in den Hof der Ernter auf.\n\nEuch wird das Glück zuteil, meinen Aufstieg zur Macht mitzuerleben.\n\nDie Verräter haben die Brücke vor uns verbarrikadiert. Macht mir den Weg frei, damit ich unbehelligt auf die andere Seite gelange.\n\nNun, da ich ein Erntermedaillon trage, kann sich mir niemand mehr widersetzen.\n\nIch werde meine Macht aber nicht an dieses Gesindel vergeuden.", sourceObjective = "Räumt die Brücke für den Obersten Kämmerer.", completion = "<Echelon grunzt.> Ihr seid spät dran.", sourceObjectiveStatus = "unverified-source-field" }
quests[57164] = { id = 57164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlingt das", description = "Die Seelen sind zwar unser Hauptziel, aber es hat sich noch eine weitere Herausforderung ergeben.\n\nDer Fluchwald ist von Verschlingern heimgesucht worden: widerliche Viecher, die sich von der Anima nähren, die wir zum Überleben benötigen. Da geht echten Jägern doch das Herz auf, oder?\n\nIch sollte dem Meister danken, dass sie nur in ein paar abgeschiedenen Nischen verblieben sind. Ich hasse den Gedanken, dass sie sich vermehren könnten. Lasst sie uns auslöschen, bevor sie eine ernsthafte Bedrohung darstellen.", sourceObjective = "Eliminiert die Verschlinger im Fluchwald.", completion = "Sobald Ihr die Angst meistert, ist Euch niemand mehr gewachsen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57171] = { id = 57171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldastwächter" }
quests[57173] = { id = 57173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sündenstein der Anklägerin", description = "Der Oberste Kämmerer wird die Brücke überqueren, wenn es ihm genehm ist.\n\nVor seiner Ankunft werdet Ihr den Sündenstein der Anklägerin an Euch bringen.\n\nWeise Venthyr wie Der Oberste Kämmerer verstecken ihren Sündenstein, damit er niemals gegen sie verwendet werden kann.\n\nDoch die Anklägerin ist zu stolz, um ihren Sündenstein zu verstecken. Stattdessen stellt sie ihn zur Schau, damit alle ihn sehen können.\n\nSie prahlt mit den vielen, vielen Sünden, die sie überwunden hat.\n\nStolz. Arrogant. Aber noch wichtiger: töricht.\n\nIhr Sündenstein liegt auf dem Altar vor uns, allem Anschein nach unbewacht. Holt ihn Euch.", sourceObjective = "Untersucht den Sündenstein der Anklägerin.", completion = "Ist das wirklich das Beste, was Ihr zu bieten habt?", sourceObjectiveStatus = "unverified-source-field" }
quests[57174] = { id = 57174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Steingeborenen", description = "Die Steinlegion ist noch nicht hier? Das ist skandalös!\n\nWenn wir nicht schnell handeln, werden die Rebellen diesen dreckigen Weiler überrennen.\n\nHier, nehmt die Anima und aktiviert ein paar der Steingeborenen am Rand von Dunkelhafen. Die restliche Anima bringt Ihr dann zur Rüstmeisterin... und sagt ihr, sie soll gefälligst ihre Arbeit machen.\n\nIch werde versuchen, mit dem Meister Zwiesprache zu halten, und ihn um Verstärkung bitten.", sourceObjective = "Sammelt den Animakäfig und erweckt dann 6 steingeborene Wächter.", completion = "Das ist alles, was von unserem Zehnt verblieben ist? Der Zehntherr akzeptiert keine Ausreden. Wir sollten schleunigst einen zweiten Zehnt sammeln, damit er uns nicht alle in den Glutdistrikt verbannt.", sourceObjectiveStatus = "unverified-source-field" }
quests[57175] = { id = 57175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inquisitor Vilhelms Sündenstein", description = "Inquisitor Vilhelm hat außergewöhnliche Vorkehrungen getroffen, um seinen Sündenstein zu schützen.\n\nEr hat ihn in mehrere Stücke zerbrochen, die er dann versteckt hat. Er dachte, sein Sündenstein wäre so sicher vor uns.\n\nDoch sein Plan hatte dieselbe Schwäche wie die der meisten: Er hat willensschwachen Untergebenen vertraut.\n\nIch habe mehrere Gräber \"befragt\", um in Erfahrung zu bringen, wo sie die Sündensteinfragmente des Inquisitors versteckt haben.\n\nFindet alle Bruchstücke dieses Steins und bringt sie zu mir.", sourceObjective = "Sammelt die 3 versteckten Sündensteinfragmente.", completion = "<Als Echelon die Sündensteinfragmente in seinen Händen hält, verbinden Animabande die Stücke miteinander und stellen den Sündenstein vollständig wieder her.>\n\nNun können wir fortfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[57176] = { id = 57176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sündensteinlieferung", description = "Der Oberste Kämmerer hat die Anklägerin aufgehalten, um uns genug Zeit zu verschaffen, den Zauberschutz ihres Sündensteins zu brechen.\n\nAber wegen Eurer Verzögerungen ist unsere Verstärkung seiner Position nun überfällig.\n\nIch werde den Sündenstein der Anklägerin einsammeln und uns zum Schauplatz des Kampfes bringen.", sourceObjective = "Fliegt mit Echelon und bringt den Sündenstein der Anklägerin zum Obersten Kämmerer.", completion = "Das ist wirklich einer der größten Sündensteine, die ich bisher gesehen habe.\n\nDen werden wir leicht ausbeuten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[57177] = { id = 57177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Neuanfang" }
quests[57178] = { id = 57178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Meister wartet", description = "<Schlundgänger/Schlundgängerin>, ich bin Generalin Kaal. Die Steingeborenen, die sich noch an ihren Eid gegenüber dem Meister erinnern, unterstehen meiner Befehlsgewalt.\n\nDer Pfad zwischen uns und Graf Denathrius wird nicht mehr von meinen Leuten gesichert. Ich ziehe meine Truppen aus diesem Viertel ab, um den Willen des Meisters andernorts zu vollstrecken.\n\nGraf Denathrius schickt mich, um Euch direkt zu ihm zu bringen. Myskia kann Euch tragen.", sourceObjective = "Trefft Euch mit Graf Denathrius.", progress = "Achtet auf Eure Manieren, wenn Ihr mit Graf Denathrius sprecht. Er ist ein Wesen, das noch älter ist als Eure Welt.", completion = "Wartet! Bitte, Schlundgänger, erlaubt mir, Euch dem Meister anzukündigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57179] = { id = 57179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Autorität von Revendreth", sourceObjective = "Nehmt den Segen des Meisters an.", progress = "Meine Augen sind überall.", completion = "Schlundgänger, erhebt Euch nun als Waffe, die mit der Macht meiner Herrschaft gesegnet ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[57180] = { id = 57180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geheimnis der Anklägerin", description = "Wo ich jetzt den Sündenstein der Anklägerin besitze, kann ich ihrer verräterischen Scharade endgültig ein Ende setzen!\n\nBeschützt mich, während ich diesen Sündenstein untersuche, und ich werde Euch zu meiner rechten Hand machen.\n\nNachdem ich sie mit meiner unglaublichen Macht zermalmt habe, werde ich die Hallen der Sühne unter meine Kontrolle bringen und die Belohnung des Meisters erhalten.\n\nDiese Großtat wird meinen Aufstieg an den Hof der Ernter einläuten!", sourceObjective = "Helft dem Obersten Kämmerer, die Anklägerin zu besiegen.", completion = "<Ein saures Lächeln durchzieht das Gesicht des Obersten Kämmerers.>\n\nDie Hallen der Sühne stehen unter meiner Kontrolle.", sourceObjectiveStatus = "unverified-source-field" }
quests[57182] = { id = 57182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal der Anklägerin", description = "Ihr befindet Euch nun in der Gegenwart eines Ernters, <Schlundgänger/Schlundgängerin>.\n\n<Der Oberste Kämmerer atmet tief ein und lächelt.>\n\nIch werde das Medaillon der Anklägerin verwenden, um meine Stellung in den Hallen der Sühne zu festigen.\n\nDerweil hat der Meister darum gebeten, dass Ihr ihm die Anklägerin und das Medaillon, das er mir geliehen hat, bringt.\n\nMyskia wird Euch in Kürze abholen. Lasst den Meister nicht warten.", sourceObjective = "Reitet auf Myskia und bringt die Anklägerin zu Graf Denathrius.", progress = "Ich gehe davon aus, Ihr habt das Medaillon, das ich dem Obersten Kämmerer geliehen habe?", completion = "<Graf Denathrius lächelt, als Ihr ihm das Medaillon übergebt.>\n\nEs freut mich zu sehen, dass man Euch große Macht anvertrauen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[57185] = { id = 57185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pflichtgebunden", description = "Willkommen im Kampf, {name}. Ihr gehört jetzt zu uns.\n\nNehmt Euch einen Moment Zeit und stellt Euch vor. Ich treffe Euch bei Draven an der Hütte.", sourceObjective = "Stellt Euch bei General Draven, Nadjia Nebelklinge und Rendel vor.", sourceObjectiveStatus = "unverified-source-field" }
quests[57189] = { id = 57189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hoffnungsbrecher brechen", description = "Die Furchthetzerin hat mit Sicherheit ihre Jäger ausgeschickt, den ganzen Fluchwald nach uns zu durchsuchen, {name}.\n\nDraven hat mich darüber informiert, dass einige ihrer besten Jäger genau in diesem Moment die Schauerkuppe absuchen. Das können wir zu unserem Vorteil nutzen. Sie zu töten, sollte ihre Aufmerksamkeit erregen.\n\n<Die Anklägerin gibt Euch verschiedene hellrote Phiolen.>\n\nSchleudert die auf ihre Jäger. Das sollte die Aufmerksamkeit der Verschlinger, die diesen Ort verseuchen, auf sich ziehen.", sourceObjective = "Benutzt die Phiole mit konzentrierter Anima, um die Hoffnungsbrecher in der Schauerkuppe zu besiegen.", completion = "Das klingt, als ob es besser als erwartet funktioniert hätte.\n\nPerfekt. Die Furchthetzerin hat keine Chance.", sourceObjectiveStatus = "unverified-source-field" }
quests[57190] = { id = 57190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie werden nicht wissen, wie ihnen geschieht", description = "Die Furchthetzerin hierherzulocken, wird sinnlos sein, wenn wir unsere Chancen nicht verbessern können. Sie wird mit Sicherheit mit einer kleinen Armee auftauchen.\n\nStellt diese Animabehälter auf. Wenn es so weit ist, werden wir ihren Inhalt freisetzen. Das wird sie und ihre Streitkräfte mit einer dicken Schicht Anima überziehen.\n\nDann sollten die Verschlinger, die diesen Ort verseuchen, von ihnen angezogen werden wie die Motten vom Licht.", sourceObjective = "Stellt 8 manipulierte Animabehälter auf.", completion = "Die Verschlinger werden sie in Stücke reißen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57198] = { id = 57198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pflichtgefühl", description = "Derek ist frei. Ich habe bei ihm viel gutzumachen.\n\nEs gibt Gerüchte über ein Treffen zwischen Jaina und ihrem Bruder.\n\nReist nach Seebrise im Sturmsangtal. Ich hoffe, dort könnt Ihr herausfinden... na ja, sagen wir, ich versuche das große Ganze im Blick zu behalten.\n\nWenn Ihr etwas interessantes herausfindet, wäre ich Euch sehr dankbar.\n\nDas sollte aber vorerst unter uns bleiben.", sourceObjective = "Belauscht Jaina Prachtmeers Treffen.", completion = "Na das ist aber interessant...\n\nIch muss schnell handeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[57205] = { id = 57205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein oder zwei Steine im Weg", description = "Dieses Territorium ist von strategischer Bedeutung für unsere Verteidigung. Wir können es diesen Monstrositäten nicht erlauben, dass sie uns zum Rückzug zwingen.\n\nBringt zwei der Positionen, die auf Eurer Karte markiert sind, unter Eure Kontrolle. Verteidigt sie vor den Angriffen der Gegner, bis die Flagge platziert und die Position eingenommen ist.", sourceObjective = "Nehmt zwei Positionen ein und verteidigt sie", sourceObjectiveStatus = "unverified-source-field" }
quests[57207] = { id = 57207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lysonias Plan", description = "Lysonia hat das Paragon in die Knie gezwungen! Die ihr zur Verfügung stehenden Mächte des Schlunds sind viel zu stark.\n\nWir müssen sie aufhalten.", sourceObjective = "Stellt Lysonia.", progress = "<Das Paragon der Demut krümmt sich vor Schmerz.>", completion = "Ich bin geschwächt, aber ich werde heilen.\n\nSie hat nach Stolz gesucht, der in mir nicht existiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[57215] = { id = 57215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maschine des Aufstiegs" }
quests[57216] = { id = 57216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Altstadt" }
quests[57217] = { id = 57217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgegrabener Hüter" }
quests[57218] = { id = 57218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgegrabener Hüter" }
quests[57219] = { id = 57219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgegrabener Hüter" }
quests[57220] = { id = 57220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einleitung des Energieprotokolls", description = "Wir haben schon viel erreicht, {name}.\n\nSobald die Energie von den Hilfssystemen umgeleitet ist, kann MUTTER die Diagnoseroutinen starten.\n\nWir müssen nur noch die letzten Schritte in die Wege leiten.", sourceObjective = "Leitet die Energie aus den Hilfssystemen der Herzkammer, der Maschine von Nalak'sha und der Schmiede des Ursprungs um. Sprecht dann mit MUTTER, um die Schmiede des Ursprungs aufzuladen.", progress = "Bisher eine durchaus bemerkenswerte Reise.", completion = "Ihr solltet Euch lieber darum kümmern, bevor die Dinge aus dem Ruder laufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57221] = { id = 57221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuerschaffung", description = "Wenn die Ramkahen noch keinen der Alarme ausgelöst haben, dann muss die Anomalie auf die Hallen des Ursprungs begrenzt sein.\n\nWir sollten dorthin zurückkehren und das untersuchen, {name}.", sourceObjective = "Trefft Magni Bronzebart außerhalb der Hallen des Ursprungs in Uldum.", completion = "Hier draußen finden wir keine Antworten.", sourceObjectiveStatus = "unverified-source-field" }
quests[57222] = { id = 57222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hallen untersuchen", description = "Was auch immer vor sich geht, muss tief aus der inneren Kammer stammen. Wenn wir die Schmiede erreichen können, finden wir vielleicht ein paar Antworten.\n\nIhr solltet lieber Eure Ausrüstung überprüfen, bevor Ihr Euch hineinbegebt, {name}. Wer weiß, was da drin auf uns wartet.", sourceObjective = "Untersucht die Anomalie in den Hallen des Ursprungs.", completion = "Sollte N'Zoth Zugang zur Schmiede erhalten und ihre Macht nutzen, wäre das... katastrophal.\n\nWir haben leider nicht viel Zeit, {name}. Wenn Ihr das weiter untersuchen wollt, müsst Ihr Euch schützen.\n\nUnd da weiß ich genau das Richtige.", sourceObjectiveStatus = "unverified-source-field" }
quests[57223] = { id = 57223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgegrabener Hüter" }
quests[57225] = { id = 57225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[57226] = { id = 57226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[57228] = { id = 57228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Schauerkuppe", description = "Die Zeit ist gekommen, <Schlundgänger/Schlundgängerin>. Die Jäger der Furchthetzerin fallen über uns her.\n\nWir haben uns so gut wie möglich auf ihren Angriff vorbereitet. Hier.\n\n<Die Anklägerin gibt Euch einen verzierten Stab.>\n\nIch habe ihn aus den Vorräten angefertigt, die Ihr mir gebracht habt. Benutzt ihn, um die Truppen der Furchthetzerin zu vernichten.\n\nDer Kampf beginnt.", sourceObjective = "Besiegt 12 Truppen der Furchthetzerin.", sourceObjectiveStatus = "unverified-source-field" }
quests[57234] = { id = 57234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonnensammler" }
quests[57235] = { id = 57235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonnensammler" }
quests[57240] = { id = 57240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist Prinz Renathal?", sourceObjective = "Sprecht mit Steinkopf, dem Torwächter des Glutdistrikts.", completion = "Hier ist nicht für Euch. Hier ist für Bösewichte!", sourceObjectiveStatus = "unverified-source-field" }
quests[57243] = { id = 57243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sklavenlager der Amathet" }
quests[57245] = { id = 57245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Animateriewiederbelebung", description = "Dieses Gebiet ist reich an den Überresten gefallener Soldaten... einige von ihnen tragen noch immer einen Funken Potenzial in sich.\n\nIch habe das geschaffen, was ich die \"Animateriekugel\" nenne, mit der man die in der Gießerei verstreute Skelettmaterie wiederbeleben kann.\n\nSehen wir mal, wie viele der neuen Animate sich unserer Sache anschließen würden.\n\nWas diejenigen angeht, die es nicht tun... nun, sie sollten inzwischen ziemlich daran gewöhnt sein, getötet zu werden.", sourceObjective = "Rekrutiert 15 Animate.", progress = "Haben wir genug Animate?", completion = "Diese wiederbelebten Truppen werden sinnvoll eingesetzt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[57246] = { id = 57246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aalfilet", progress = "Ja? Was ist?", completion = "Mein Lieblingsessen! Woher wusstet Ihr das?\n\nIch werde es für das Lager zubereiten. Alle werden es genießen." }
quests[57247] = { id = 57247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefenrochenflügel", progress = "Ja? Was ist?", completion = "Das ist ein schöner, saftiger Flügel, den Ihr da habt.\n\nIch werde ihn zubereiten. Es ist genug für alle da." }
quests[57248] = { id = 57248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riesenkrabbenbein", progress = "Ja? Was ist?", completion = "Wow, das ist ja wirklich riesig. Sieht köstlich aus!\n\nIch werde ein wenig Suppe für heute Abend vorbereiten. Alle werden sie lieben." }
quests[57249] = { id = 57249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine zeitige Einladung", description = "Die Zeit ist gekommen, sich an die Vergangenheit zu erinnern und unsere Abenteuer in Azeroth und darüber hinaus zu feiern. \n\nUm dieses Ereignis zu würdigen, veranstaltet der bronzene Drachenschwarm eine Feier, und Ihr seid eingeladen! \n\nKommt zu den Höhlen der Zeit und zeigt dieses Ticket vor, um eingelassen zu werden!", sourceObjective = "Bringt die Einladung von den Zeitwanderern zu Chromie in den Höhlen der Zeit.", completion = "Willkommen! Es ist die besondere Zeit des Jahres, in der der bronzene Drachenschwarm all das feiert, was über die Jahre passiert ist, und Ihr, {name}, seid der Ehrengast!\nKommt und feiert beim großen Festmahl, schwingt die Hüften in der \"Diskothek der Zeit\" oder nehmt eine Quest an, um einige der größten Bedrohungen für Azeroth abzuwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[57251] = { id = 57251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eroberungsbelohnung" }
