quests[57256] = { id = 57256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arena der Sturmerwählten" }
quests[57261] = { id = 57261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aspiranten auf dem Pfad", description = "Wenn Ihr vor die Archon treten wollt, müsst Ihr einen bestimmten Pfad beschreiten. Zum Glück ist dieser auch in diesen schlimmen Zeiten gut ausgetreten und begehbar.\n\nObwohl Ihr nicht dazu bestimmt seid, <Kyrianer/Kyrianerin> zu werden, könnten unsere Gepflogenheiten für Euch interessant sein. Lernt gut, lernt schnell und vielleicht wird die Archon auf Euch aufmerksam und gewährt Euch die Audienz, die Ihr anstrebt.\n\nAspirantin Kleia wird Euch den Weg weisen. Möge der Blick der Archon auf Euch ruhen.", sourceObjective = "Reist mit Kleia.", completion = "Eure Reise beginnt gerade erst, {name}. Ich hoffe, Ihr könnt uns helfen, und dass auch wir Euch helfen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[57263] = { id = 57263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kreislauf der Anima: Ätherwyrms", description = "Schmiede ist kalt, ja? Braucht VIEL Anima, um angefeuert zu werden.\n\n<Sika zieht ihre Schriftrolle zu Rate.>\n\nFrüher war überall Anima, ja? Jetzt nur noch versteckt. Kleine Mengen an seltsamen Orten.\n\nWir wissen, dass Ätherwyrms... flatternde, schuppige Dinger in Blau... Anima fressen. Sind nicht tot, also finden sie immer noch Anima zum Fressen, ja?\n\nVielleicht können wir das, was sie gefressen haben, zum Anfeuern der Schmiede verwenden. Wird sie wahrscheinlich umbringen.\n\nTraurig, ja. Aber! Wir nehmen nicht sehr viel. Nur ein bisschen.", sourceObjective = "Tötet Ätherwyrms, um 25 leuchtende Eingeweide zu sammeln.", progress = "Habt Ihr Anima gefunden? Vielleicht nur ein wenig?", completion = "<Sika stochert in der matschigen Substanz.>\n\nEs leuchtet. Das bedeutet Anima. Schmiedin wird zufrieden sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[57264] = { id = 57264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die nahende Stunde der Offenbarung", description = "Ah! Gut. Ihr seid dem Ruf gefolgt.\n\nWie Ihr seht, benötigen hier viele Aspiranten unsere Hilfe. Es sind fast schon zu viele für die anderen Jünger und mich. Und bei einigen ist die Not besonders groß.\n\nBesonders gefährlich ist es für Aspiranten, die kurz vor einer Offenbarung stehen. In diesem kritischen Moment müssen wir ihnen unbedingt zur Seite stehen und eingreifen.\n\nIhr müsst ihnen einen kleinen Schubs geben, in die eine oder andere Richtung.\n\nFindet die Verwundbarsten unter Euren Mitaspiranten und tut, was Ihr könnt, damit sie den richtigen Weg finden.", sourceObjective = "Inspiriert 11 verwundbare Aspiranten, endlich zu handeln.", completion = "Euer Dienst wurde zur Kenntnis genommen. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[57265] = { id = 57265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kreislauf der Anima: Folgen der Dürre", description = "In vergangenen Zeiten war es ein Kinderspiel, eine Schmiede zu schüren. Die Animaextraktoren konnten ununterbrochen ihre Arbeit verrichten, ohne jemals trocken zu laufen.\n\nJetzt ist es schon ein Risiko, einen Extraktor nur einzuschalten. Ätherwyrms finden keine Animaströme mehr, an denen sie sich nähren können, und werden von jeglicher Animaquelle angezogen. Sie sind ein ständiges Ärgernis.\n\nIch muss Euch bitten, das Risiko ihrer Aufmerksamkeit auf Euch zu nehmen. Aktiviert den Extraktor und bewacht ihn, bis er die wenige verbliebene Anima gesammelt hat.\n\nBringt mir das Ergebnis seiner Arbeit. Hoffen wir, dass es genug sein wird.", sourceObjective = "Holt ein kondensiertes Animapartikel aus dem Animaextraktor.", progress = "Funktioniert der Extraktor? Wie viel konntet Ihr beschaffen?", completion = "Das ist... irgendwie mehr und auch weniger, als ich erwartet hatte. Es muss genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57266] = { id = 57266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die erste Läuterung", description = "Diese Situation mag Euch bekannt vorkommen, {name}.\n\nAls Ihr Pelagos gefunden habt, unterzog er sich einem ähnlichen Ritus. Wie Ihr gesehen habt, kann das ein gewaltsames Ende nehmen.\n\nMan verlangt jetzt zum ersten Mal von Euch, die Bürden, die für Euer Verharren in einem sterblichen Leben sorgten, hervorzubringen. Das könnte ein schmerzhafter Vorgang sein. Er ist es für viele.\n\nFür Euch ist es der Weg, den Ihr beschreiten müsst, um Eure Ziele zu erreichen. Damit Ihr das Recht erlangt, an unserer Seite zu stehen und gehört zu werden. Erst dann können wir Eure Botschaft der Archon persönlich überbringen.\n\nKonzentriert Euch. Wenn Ihr bereit seid, werden wir beginnen.", sourceObjective = "Unterzieht Euch der ersten Läuterung.", completion = "Dieser Moment ist es wert, gefeiert zu werden, {name}.\n\n\n\nIhr habt es geschafft. Sie sind gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57267] = { id = 57267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kreislauf der Anima: Blumenmacht", description = "Um Schmiede anzufeuern, brauch ich mehr Anima. Immer mehr. Für Schmiede ist es niemals zu viel!\n\n<Sika zieht ihre Schriftrolle zu Rate und nickt nachdrücklich, während sie liest.>\n\nAuf den Feldern draußen gibt es eine leuchtende Blume. Das runde Dings drinnen. Zwiebel? Es leuchtet. Hat also Anima. Aus der Erde, glauben wir.\n\nLaut Schriftrolle heißt sie Adrimas Lilie. Wir wissen nicht, wer Adrima ist. Aber die Lilie ist gut.\n\nHolt auch Blüten. Nicht nur Zwiebeln. Blütenblätter machen Provosten auch glücklich.\n\nVielen Dank!", sourceObjective = "Sammelt 6 Exemplare von Adrimas Lilie.", progress = "Habt Ihr die Blumenzwiebeldinger?", completion = "Oh. Sie duften gut. Und sie leuchten stark.\n\nDas ist gut. Ja.", sourceObjectiveStatus = "unverified-source-field" }
quests[57269] = { id = 57269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hand des Zweifels", description = "Schnell! Wir haben keine Zeit zu verlieren. Lysonia hat Eridia so weit geschwächt, dass sie fallen könnte. Unser Paragon wird alles tun, was ihr möglich ist, aber wir müssen einschreiten.\n\nWir werden Lysonia herausfordern und Eridia vielleicht etwas mehr Zeit verschaffen.\n\nDiese sogenannte Hand des Zweifels wird kein leichter Gegner sein. Seid bereit, {name}.", sourceObjective = "Besiegt Lysonia, Hand des Zweifels.", completion = "Dass Ihr Euch uns jetzt, an der Schwelle dieses Verrats, anschließt, ist eigenartig.\n\n<Das Paragon der Reinheit mustert Euch mit durchdringendem Blick.>\n\nIhr habt Euch gut geschlagen. Die Archon wird noch heute von Eurem Beitrag erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[57270] = { id = 57270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tempel der Reinheit", description = "Seid gegrüßt.\n\nIch bin Kosmas, Jünger des Tempels der Reinheit.\n\nDer Tempel ist ein Ort der Läuterung. Er dient allein dem Zweck, Aspiranten von den Bürden zu befreien, die sie aufgrund ihres Lebens mit sich herumtragen. Er ist ein Ort des stillen Nachdenkens, sogar für die, die ihre Bürden bereits abgestreift haben.\n\nDie Zahl derjenigen, die bei uns nach Reinheit suchen, ist in letzter Zeit immer mehr gewachsen. Meine Mitjünger sind an der Grenze ihrer Belastbarkeit. Ich bin hier, weil ich um die Hilfe aller Aspiranten bitten möchte, die geistig dazu in der Lage sind.\n\nEure Hilfe wird benötigt. Bitte meldet Euch umgehend bei der Hand der Reinheit.", sourceObjective = "Trefft Euch mit der Hand der Reinheit am Tempel der Reinheit.", completion = "Danke, dass Ihr Eure Hilfe angeboten habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[57271] = { id = 57271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Handelsdistrikt" }
quests[57272] = { id = 57272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutgebundenes Abbild" }
quests[57274] = { id = 57274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld des Rüstmeisters", progress = "Um den Feind zu besiegen, braucht Ihr Ausrüstung im Topzustand. Wenn Ihr Euch keine mächtigere Ausrüstung beschaffen konntet, kann ich für Euch welche vom Rüstmeister anfordern.", completion = "Sieg um jeden Preis." }
quests[57275] = { id = 57275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas geht Euch durch den Kopf", description = "<Ihr schaut in den Kristall und das Licht um Euch verwandelt sich langsam in tintigen Rauch. Eine imposante Präsenz erdrückt Euch förmlich und flüstert Euch etwas Unverständliches ins Ohr. Ihr sucht nach der Quelle, könnt aber nichts sehen. Das überwältigende Gefühl wird hingegen immer stärker. Eure Gedanken verschwimmen, die Dunkelheit wird immer schwärzer und der Lärm wird ohrenbetäubend.\n\nIhr nehmt all Euren Willen zusammen und bleibt entschlossen und standhaft...\n\nDas Licht ist zurückgekehrt und der Lärm verstummt. Ihr steht mit einem unscheinbaren Kristall in der Hand da.\n\nVielleicht weiß Furorion mehr darüber...>", sourceObjective = "Bringt den Leerenfokus zu Furorion in die Herzkammer.\n\nBereitgestellter Gegenstand:", completion = "<Furorions Stirn legt sich in Falten, als er den Kristall sieht.>\n\nEin Glück, dass Ihr ihn mir gebracht habt. Beeindruckend, dass Ihr ihn bei Euch tragen und gleichzeitig Eure geistige Gesundheit behalten konntet. Das... könnte uns sogar eine Chance bieten.\n\n<Furorion streicht sich gedankenverloren über das Kinn.>\n\nIch werde Euch nichts vormachen, {name}, es wird auf jeden Fall gefährlich. Aber ich bin äußerst zuversichtlich, dass Ihr der Aufgabe gewachsen seid. Also lasst uns N'Zoths eigene Macht gegen ihn richten.", sourceObjectiveStatus = "unverified-source-field" }
quests[57276] = { id = 57276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Fokus bewahren", description = "Bis jetzt enthält der Fokus nur einen kleinen Teil der wahren Macht von N'Zoth. Wenn wir ihn weiter ermächtigen würden, könnten wir noch mächtigere Waffen schaffen, die wir gegen ihn einsetzen können.\n\nN'Zoths Einfluss ist überall, {name}, und besonders stark ist er bei mächtigen Feinden. Bezwingt sie und entreißt ihnen die Überreste der Macht des Alten Gottes.", sourceObjective = "Beschafft 20 Wahnsinnsfetzen. Ihr könnt sie von Bossen in Ny'alotha und Weltbossen, durch Siege auf Schlachtfeldern und in Arenen oder durch ehrenhafte Siege erhalten.", progress = "Wir wagen hier einen gefährlichen Schachzug, {name}. Vorsicht ist dabei von höchster Bedeutung.", completion = "Ausgezeichnet. Die sollten genau das bieten, was wir brauchen.\n\nIch werde den Gegenständen die Verderbnis entziehen und in den Fokus umlenken. Danach könnt Ihr damit noch mächtigere Gegenstände erschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57278] = { id = 57278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt mir ihre Köpfe!", description = "Ich habe am Grab von Vistara dem Gefallenen geschworen, dass ich ihm das Haupt desjenigen bringen werde, der ihn verraten hat.\n\nObwohl das schon Äonen her ist, ist es ein Schwur, an den ich gebunden bin. Ganz gleich, welches Schicksal dem Verräter letztlich widerfahren sein mag, wahrscheinlich ist sein Kopf immer noch in der Nähe zu finden.\n\nTötet alle hier. Sicherlich ist einer von ihnen der Verräter... oder im Besitz seines Kopfes.", sourceObjective = "Sammelt 10 Verräterköpfe.", progress = "Habt Ihr den Verräterkopf?", completion = "Ich habe ebenfalls viele andere gebeten, Köpfe zu sammeln! Also selbst wenn sich der Kopf des Verräters nicht hier befindet, werden wir ihn schließlich finden!", sourceObjectiveStatus = "unverified-source-field" }
quests[57282] = { id = 57282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Magierviertel" }
quests[57284] = { id = 57284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klinge aller Klingen", description = "Das beste Schwert aller Zeiten ist verloren gegangen!\n\nIn all Euren erbärmlichen Abenteuern seid Ihr einer solchen Klinge nicht begegnet, <Sterblicher/Sterbliche>. Feindspalter wurde geschmiedet, um die Titanen niederzustrecken!\n\nIch habe es gegen unzählige Gegner geschwungen. Abgesandte des Lichts, Schergen der Leere, Wichtigtuer aus den Gärten des Lebens... alle sind vor mir gefallen! Bald werden die Ebenen der Wirklichkeit vor meiner Größe niederknien!\n\nDas heißt, sobald ich meine Waffe finde.\n\nIch bestehe darauf, dass Ihr mir helft, sie zurückzubekommen. Ich weiß, dass sie hier irgendwo ist!", sourceObjective = "Findet Feindspalter unter all den vergessenen Waffen.", progress = "Habt Ihr Feindspalter gefunden? Nun? HABT IHR?!", completion = "Feindspalter! Jetzt beginnt mein Eroberungsfeldzug!\n\nIhr... Ihr tut so, als hättet Ihr schon bessere Schwerter gesehen, Sterblicher. Wie könnt Ihr es wagen?\n\nWartet nur ab. Ihr werdet vor mir niederknien wie alle anderen auch!\n\n<Das Animat murrt und knurrt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[57288] = { id = 57288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewertung Eurer Stärke", description = "Die bevorstehende Prüfung wird Euch Dinge abverlangen, die Ihr Euch wahrscheinlich nur ausmalen könnt.\n\nIch schließe aus Eurer Vergangenheit und aus Eurer Haltung, dass Kämpfe Euch nicht fremd sind. Ich wüsste gerne, wo Eure Stärken liegen, damit wir uns vor Eurer Prüfung um mögliche Schwächen kümmern können.\n\nIhr werdet auf drei prätorianische Soldaten treffen, die eigens zu diesem Zweck erschaffen wurden. Jeder ist stärker als sein Vorgänger.\n\nBesiegt sie alle, und ich kann davon ausgehen, dass ihr stark genug seid, um weiterzumachen.", sourceObjective = "Besiegt die 3 prätorianischen Sparringhelfer.", completion = "Beeindruckend. Ich sehe, ich kann Euch nicht mehr viel beibringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57290] = { id = 57290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beginn des Abstiegs", description = "Um seinen Geist vor den Alten Göttern zu schützen, bedarf es eines Objekts reiner Verderbnis. Viele wissen es nicht, aber solch ein Objekt existiert und ruht unter den Schlackegruben des Pechschwingenabstiegs.\n\nBis vor Kurzem hat einer meiner Agenten dieses Gebiet bewacht und verdächtige Aktivitäten auf das Genaueste aufgezeichnet. Leider ist der Kontakt zu diesem Agenten abgebrochen. Offensichtlich sind wir nicht die Einzigen, die davon wissen.\n\nWenn wir Antworten finden wollen, gibt es nur einen Ort, um danach zu suchen.\n\nUnsere Reise geht weiter, {name}. Der Schwarzfels erwartet uns.", sourceObjective = "Beschafft die verderbte schwarze Drachenschuppe vom Pechschwingenabstieg auf dem Schwarzfels in der Brennenden Steppe.", progress = "Habt Ihr gefunden, worüber wir gesprochen haben?", completion = "Die Schuppen der Verderbnis dienen jetzt als Schutz für jene, die ihr Widerstand leisten.\n\nWie passend.\n\nNun lasst uns sehen, wozu ein {class} Eures Kalibers mit angemessener Kleidung fähig ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[57291] = { id = 57291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kammer der Ersten Reflexion", description = "Ah, Athanos. Wie vorgesehen ist er weiterhin unbesiegt.\n\nDennoch habt Ihr alle meine Erwartungen übertroffen. Ihr seid stärker als die vielen, die vor Euch kamen.\n\nIhr seid aus einem bestimmten Grund hier, und Kleia hat einen Weg vorgezeichnet, von dem sie glaubt, dass Ihr ihn beschreiten könnt. Ich stimme ihr zu. Ich habe den Weg zum letzten Ritus des Prüfsteins geöffnet.\n\nFolgt dem Pfad nach Südosten. Dort findet Ihr den Eingang zur Kammer der Ersten Reflexion.\n\nKleia wird Euch weitere Anweisungen erteilen. Geht und dient, {name}.", sourceObjective = "Sprecht mit Kleia in der Kammer der Ersten Reflexion.", completion = "Sammelt Euch. Auf diese Weise werdet Ihr Euren Weg zur Archon finden. Dessen bin ich mir sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[57298] = { id = 57298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was \"wirklich\" passiert ist...", description = "Ihr seid über die Jahre weit gekommen, {name}.\n\nOb in Euren Anfängen als Mädchen für alles oder später als <Retter/Retterin> von ganz Azeroth – Ihr habt so viel für die Sicherheit unserer Welt getan.\n\nAber warum sollten wir nur rumstehen und versuchen, uns an alte Zeiten zurückzuerinnern? Reisen wir lieber einfach in der Zeit zurück und erleben die ganzen aufregenden Momente nochmal!\n\nKeine Sorge, es gibt Abermillionen von Zeitwegen. Da finde ich bestimmt einen, in dem Ihr nicht sterbt.", sourceObjective = "Brecht mit Chromie aus den Höhlen der Zeit auf, um Übeltäter der Vergangenheit zu besiegen.", completion = "Juchu! Hat das nicht riesig Spaß gemacht? Und Euch ist dabei überhaupt nichts Schlimmes passiert!\n\n<Chromie zwinkert Euch verschmitzt zu.>", sourceObjectiveStatus = "unverified-source-field" }
quests[57299] = { id = 57299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysteriöser Sarkophag" }
quests[57300] = { id = 57300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeitsoldat", description = "Vor langer Zeit war das Land des Alteractals friedvoll. Doch als die Frostwölfe dort einzogen, wurde daraus ein heiß umkämpftes Gebiet zwischen ihnen und den Sturmlanzen. Die Kämpfe dauerten tagelang an.\n\nNun, die Schlacht ist immer noch nicht vorbei, da die Bronzedrachen einen Weg gefunden haben, wie Ihr die frühen Tage des Tals erneut erleben könnt.", sourceObjective = "Verdient 500 Ehre in Korraks Rache.", completion = "Die Schlachten um Alterac waren Blutbäder. Ich bin froh, dass sie vorbei sind. Ach Quatsch, sie laufen ja noch! Der Kreislauf der Zwietracht findet kein Ende.", sourceObjectiveStatus = "unverified-source-field" }
quests[57301] = { id = 57301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harte Mischung", description = "Ich habe Euren Erfolg beim Trankvorrat mitverfolgt und ich denke, Ihr könnt mir helfen. In diesem größeren Reservoir kreieren wir gefährlichere Mischungen!\n\nEs gibt drei verschiedene triefende Zutaten, die wir in unterschiedlichen Kombinationen zusammenmischen, um gewaltige Kreaturen zu erschaffen. Sobald ausreichend Zutaten zum Reservoir hinzugefügt wurden, nimmt die Mischung Form an und eine Kreatur wird erscheinen!\n\nBringt eine beliebige Kombination der Zutaten verpesteter Schlamm, viskoses Öl oder mischbarer Schlamm zum Reservoir der gemischten Monstrositäten.", sourceObjective = "Bringt eine beliebige Kombination aus verpestetem Schlamm, viskosem Öl oder mischbarem Schlamm zum Reservoir der gemischten Monstrositäten.", progress = "Habt Ihr die Mischung fertig?", completion = "Ihr könnt so viele Zutaten hinzufügen, wie Ihr möcht. Wo mehr reinkommt, kommt auch mehr raus!", sourceObjectiveStatus = "unverified-source-field" }
quests[57302] = { id = 57302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Friedhöfe im Alteractal", description = "Die Friedhöfe im Alteractal sind äußerst wertvolle Gebiete. Beide Seiten, die Horde und die Allianz, kämpfen verbissen um diese geheiligten Stätten. {name}, seid Ihr bereit die Kämpfe zu unterstützen?\n\nIch möchte, dass Ihr einen gegnerischen Friedhof besetzt. Sucht einen Friedhof mit einem Hordenbanner in seiner Mitte und reißt es heraus! Wenn Ihr das schafft, ist meine Aufgabe an Euch erfüllt...\n\nSolltet Ihr es schaffen, den Friedhof für einige Minuten zu halten, werden unsere Verstärkungstruppen eintreffen, um Euch bei der Verteidigung zu unterstützen.", sourceObjective = "Erobert einen Friedhof und kehrt zu Unteroffizier Durgen Sturmlanze in Dun Baldar zurück.", completion = "Gute Arbeit! Friedhöfe sind lebenswichtig für unseren Einfluss im Alteractal. Mit jedem Friedhof den Ihr erobert, helft Ihr der Allianz dabei, ihre Herrschaft im Tal zu sichern. \n\nGeht nun, {name}. Zieht wieder in die Schlacht, und falls Ihr einen von der Horde besetzten Friedhof seht... Ihr wisst ja was zu tun ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[57303] = { id = 57303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Rüstmeister", description = "{name}, unser Rüstmeister hat mich angewiesen, die neuen Rekruten direkt zu ihm zu schicken. Er benötigt dringend Vorräte aus Kisten, die in den Minen von Alterac eingelagert sind und aller Wahrscheinlichkeit nach wird er Euch entsenden, um sie zu beschaffen.\n\nFolgt einfach der Straße. Ihr findet den Rüstmeister im Westen.", sourceObjective = "Sprecht mit dem Rüstmeister der Sturmlanzen.", completion = "Ah, endlich sind frische Truppen eingetroffen, {name}. Mit etwas Glück könnt Ihr hier schnell was erleben und an Erfahrung gewinnen!\n\nSprecht noch einmal mit mir! Ich habe da ein paar Aufgaben, die ich gerne mit Euch besprechen würde...", sourceObjectiveStatus = "unverified-source-field" }
quests[57304] = { id = 57304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Mine erobern", description = "In den Minen des Alteractals ist noch weit mehr zu finden als bloßes Erz. Sowohl die Frostwölfe als auch die Sturmlanzen haben große Mengen ihrer Ausrüstung in der Eisenschacht- und der Eisbeißermine untergebracht... was eigentlich keine schlechte Idee ist, solange wir die Kontrolle über sie behalten!\n\nBesetzt eine Mine und kehrt zu mir zurück! Um eine Mine zu erobern, betretet eine vom Feind kontrollierte Mine und tötet den dortigen Anführer. Nachdem Ihr das getan habt, gehört die Mine uns und wir werden Truppen zu ihrem Schutz entsenden!", sourceObjective = "Erobert eine Mine, die die Sturmlanzen noch nicht kontrollieren, und kehrt dann zu Unteroffizier Durgen Sturmlanze im Alteracgebirge zurück.", completion = "Ihr habt es geschafft! Gut gemacht, {name}!\n\nWenn wir erstmal eine Mine kontrollieren und dort Truppen stationiert haben, wird es viel einfacher die dortige Ausrüstung und Mineralien einzusammeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[57305] = { id = 57305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rüstungsfetzen", description = "Im Alteractal wird ständig gekämpft und der Nachschub, den wir aus Eisenschmiede bekommen, reicht nicht, um unsere erfahrenen Truppen auszustatten.\n\nWenn Ihr Rüstungsfetzen auf dem Schlachtfeld findet, dann unterstützt unsere Kriegsbemühungen und bringt mir diese Stücke!", sourceObjective = "Bringt Murgot Tiefenschmied in Dun Baldar 20 Rüstungsfetzen.", progress = "Habt ihr mir Rüstungsfetzen mitgebracht, {name}?", completion = "Das sind ein paar recht gute Stücke, {name}. Ich kann sie nutzen, um neue Ausrüstung für unsere Truppen herzustellen.\n\nWenn ich genug davon bekomme, dann können vielleicht sogar unsere bewährten Kampfeinheiten in den Kampf eintreten!", sourceObjectiveStatus = "unverified-source-field" }
quests[57306] = { id = 57306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Rüstungsfetzen", progress = "{name}, wir brauchen mehr Rüstungsfetzen, um unsere Truppen zu versorgen!", completion = "Das sind ein paar recht gute Stücke, {name}. Ich kann sie nutzen, um neue Ausrüstung für unsere Truppen herzustellen.\n\nWenn ich genug davon bekomme, dann können vielleicht sogar unsere bewährten Kampfeinheiten in den Kampf eintreten!" }
quests[57307] = { id = 57307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Türme und Bunker", description = "Die Türme und Bunker in diesem Tal sind Schlüsselverteidigungspositionen und daher sollten wir so viele wie möglich davon unter Kontrolle halten! Geht und erobert einen vom Feind kontrollierten Turm oder Bunker.\n\nBetretet dafür einen mit einem Hordenbanner. Im Inneren befindet sich ein weiteres Banner. Zieht das Banner heraus und ein weißes Banner der Allianz wird an seiner Stelle erscheinen.\n\nDamit habt Ihr meinen Auftrag erfüllt. Wenn Ihr das eroberte Gebäude lange genug haltet, ohne dass die Horde es zurückgewinnt, gehört es uns!", sourceObjective = "Zerstört das Banner im Inneren eines gegnerischen Bunkers oder Turms. Kehrt anschließend zu Unteroffizier Durgen Sturmlanze in Dun Baldar zurück.", completion = "Ich habe eine Feldnachricht erhalten, nach der Ihr dabei geholfen habt, ein feindliches Banner zu sichern. Gute Arbeit, {name}! Nach der Vernichtung der feindlichen Schützen können wir weiter ins Feindesland vordringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[57309] = { id = 57309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Angriff soll beginnen!" }
quests[57310] = { id = 57310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Eisenschachtmine", description = "Bevor die Schlacht begann, lagerten wir Vorräte für Dun Baldar in der Eisenschachtmine. Die Troggs, die dort hausten, waren kein Problem solange wir Ersatztruppen hatten, die die Mine bewachen konnten, aber da wir nun gegen die Horde kämpfen, können wir sie nicht mehr kontrollieren.\n\nWir brauchen die Vorräte in der Eisenschachtmine, {name}. Betretet die Mine und bring mir eine Ladung.", sourceObjective = "Bringt 10 Vorräte der Eisenschachtmine zum Rüstmeister der Allianz in Dun Baldar.", progress = "Habt Ihr die Vorräte, {name}? Wir können nicht genug davon haben!", completion = "Danke, {name}! Ich werde sie einem guten Zweck zuführen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57311] = { id = 57311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Eisbeißermine", description = "Die Eisbeißermine ist ein Vorratslager für die Horde. Ich vertrage das Essen nicht, das sie ihren Truppen reichen und der Zustand ihrer Waffen und Rüstungen ist grauenhaft! Aber... in Zeiten wie diesen, in denen Vorräte so wichtig sind, können wir wirklich alles verwenden, was sie haben. \n\nBetretet die Eisbeißermine und bringt mir ihre Vorräte. Dies sollte der Allianz helfen sich weiterhin gut im Kampf zu bewähren und die Soldaten der Horde schwächen.\n\nViel Erfolg, {name}. Die Mine ist im entfernten Süden, tief im Territorium der Horde.", sourceObjective = "Bringt 10 Vorräte der Eisbeißermine zum Rüstmeister der Allianz in Dun Baldar.", progress = "Habt Ihr die Eisbeißermine im Gebiet der Horde betreten, {name}? Habt Ihr die Vorräte?", completion = "Ihr habt sie! Gut gemacht, {name}! Ich werde dann mal durch die Vorräte durchgehen und sehen was wir für unsere Truppen gebrauchen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[57312] = { id = 57312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Friedhöfe von Alterac", description = "Die Frontlinien in diesem Tal sind in ständiger Bewegung. Die Gebietsgrenzen bewegen sich hin und her, während wir unseren Feinden in tödlichen Schlachten gegenüber treten. Doch um die Friedhöfe, {name}, wird am grimmigsten gekämpft.\n\nIch möchte, dass Ihr einen von der Allianz besetzten Friedhof angreift! Sucht einen Friedhof mit einem Allianzbanner in seiner Mitte und reißt es aus dem Boden.\n\nWenn Ihr das schafft, ist meine Aufgabe an Euch erfüllt...\n\nSolltet Ihr es außerdem schaffen, den Friedhof für einige Minuten zu halten, wird dieser uns gehören und unsere Truppen werden kommen, um Euch bei der Verteidigung dieser wichtigen Position zu unterstützen.", sourceObjective = "Erobert einen Friedhof und kehrt zu Korporal Teeka Murrblut im Dorf der Frostwölfe zurück.", completion = "Gute Arbeit, {name}! Mit jedem weiteren Friedhof, den wir kontrollieren, wandern die Geister unserer Feinde mehr und mehr verloren und ziellos herum.", sourceObjectiveStatus = "unverified-source-field" }
quests[57313] = { id = 57313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit unserem Rüstmeister", description = "{name}, der Rüstmeister der Frostwölfe sucht nach Lehrlingen für Aufgaben, die in die Minen des Alteractals führen. Sprecht mit ihm; er wird Euch mehr berichten.\n\nFolgt der Straße westlich in die Kaserne, dann nehmt den westlichen Ausgang und Ihr findet unseren Rüstmeister.", sourceObjective = "Sprecht mit dem Rüstmeister der Frostwölfe.", completion = "Seid gegrüßt, {name}! Es ist immer wieder eine Freude, jemanden wie Euch zu treffen, der bereit ist, seinen Beitrag für die Horde zu leisten. Sprecht also noch einmal mit mir. Ich habe äußerst wichtige Aufgaben für Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[57314] = { id = 57314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Mine erobern", description = "So wie Kämpfe im Gebiet des Alteractals wüten, so wüten sie auch durch die Eisbeißer- und Eisenschachtminen. Beide bedeuten enorme Ressourcen an Mineralien und beide werden als Lager genutzt; daher ist es kein Wunder, dass sie so heiß begehrt sind!\n\nHelft uns in der Schlacht, {name}! Erobert für die Horde eine Mine! Begebt Euch zu einer Mine, die noch nicht von uns kontrolliert wird und tötet den dortigen Anführer! Sobald Ihr das geschafft habt, schicken wir Truppen aus, um die Mine zu bewachen!", sourceObjective = "Erobert eine Mine und kehrt zu Korporal Teeka Murrblut im Dorf der Frostwölfe zurück.", completion = "Ihr habt eine Mine erobert! Jetzt wo unsere Krieger die Mine vor Angriffen beschützen, wird es uns viel leichter fallen, dort Mineralien abzubauen und die dort eingelagerten Vorräte zu bergen.\n\nHervorragende Arbeit, {name}. Diese Tat ist ein großer Gewinn für unsere Kriegsanstrengungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57315] = { id = 57315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Türme und Bunker", description = "Die Türme und Bunker in diesem Tal sind wichtige Stellungen und daher müssen wir sie möglichst alle erobern und halten! Genug geredet... Erobert einen vom Feind kontrollierten Turm oder Bunker.\n\nBetretet dafür einen mit einem Banner der Allianz. Im Inneren befindet sich ein weiteres Banner. Zieht das Banner heraus und ein weißes Hordenbanner wird an seiner Stelle erscheinen.\n\nDamit habt Ihr meinen Auftrag erfüllt. Wenn Ihr das eroberte Gebäude lange genug haltet, ohne dass die Allianz es zurückgewinnt, gehört es uns!", sourceObjective = "Erobert einen gegnerischen Turm oder Bunker und kehrt anschließend zu Korporal Teeka Murrblut im Dorf der Frostwölfe zurück.", completion = "Ich habe von Eurer erfolgreichen Mission gehört! So gefällt mir das...\n\nUnsere Truppen können nun ungehindert die feindlichen Stellungen stürmen. Bald werden diese Schwächlinge einsehen, dass das Alteractal kein Ort für sie ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[57316] = { id = 57316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Leiter", description = "Im Theater der Schmerzen, <Bruder/Schwester>, erstrahlen Legenden wie Sterne.\n\nHört mir zu, <Bruder/Schwester>. Wenn Ihr den Mut habt, diese heilige Arena zu betreten, bekommt Ihr es mit den größten Gefahren zu tun, die Ihr Euch vorstellen könnt! Der Kampf ist hart und Ihr müsst mit ungemütlichen Hindernissen klarkommen. Nur jene, die zusammenarbeiten, werden zum Champion gekrönt.\n\nSammelt Eure Truppe und stellt Euch dieser Herausforderung! Betretet das Theater der Schmerzen, besiegt alle Widersacher. Beweist, dass Ihr es an die Spitze schaffen könnt!", sourceObjective = "Besiegt 3 Gegner im Theater der Schmerzen.", progress = "Seid gegrüßt, Bruder. Habt Ihr Euch dem Wahnsinn der Arena gestellt?", completion = "Gut gekämpft, Bruder! Ihr seid auf dem Weg zur Spitze!\n\nAber vernachlässigt das Training nicht und seid bereit. In Maldraxxus hat es immer ein Herausforderer auf Euren Platz abgesehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57317] = { id = 57317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beutezug im Feindesland", description = "Wenn Ihr gegen den Feind kämpft, sammelt die Fetzen seiner Rüstungen ein und bringt sie zu mir. Aus den Fetzen werde ich neue Rüstungen für unsere eigenen Truppen herstellen!", sourceObjective = "Bringt 20 Rüstungsfetzen zu Schmied Regzar im Dorf der Frostwölfe.", progress = "Wie läuft die Jagd, {name}. Habt Ihr irgendwelche Rüstungsfetzen für mich?", completion = "Die werden ihren Zweck erfüllen. Ich werde sie einschmelzen und reparieren und niemand wird je merken, dass sie von diesen feigen Sturmlanzen stammen!\n\nDanke, {name}. Und lasst mich Eure Rüstung aufbessern...", sourceObjectiveStatus = "unverified-source-field" }
quests[57318] = { id = 57318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Beute!", progress = "Ich brauche mehr Rüstungsfetzen, {name}! Habt Ihr mir welche mitgebracht?", completion = "Und wieder muss ich Euch danken, {name}. Ihr macht der Horde alle Ehre..." }
quests[57320] = { id = 57320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Startet den Angriff!" }
quests[57321] = { id = 57321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Eisbeißermine", description = "Die Eisbeißermine im Norden war einst ein idealer Ort, um zusätzliche Vorräte zu lagern, aber da die Kämpfe mit den Sturmlanzen nun härter werden, haben wir nicht immer die notwendigen Soldaten über, um sie an der Mine zu positionieren und diese zu bewachen. Daher fällt die Kontrolle über diese Mine oft an die Allianz oder an Untergrundvölker...\n\nAber wir benötigen dennoch unsere Vorräte, {name}! Geht zu der Eisbeißermine und bringt mir eine Ladung. Seid wachsam, was unsere Feinde anbelangt, die Übermacht in der Schlacht kann sich an jenem Ort schnell ändern...", sourceObjective = "Bringt 10 Vorräte der Eisbeißermine zum Rüstmeister der Horde in die Burg Frostwolf.", progress = "Wart Ihr in der Eisbeißermine, {name}? Habt Ihr die Vorräte nach denen ich fragte?", completion = "Ah, Ihr habt Sie bekommen. Gute Arbeit, {name}! Die Vorräte sind schon etwas moderig, nachdem sie so lange in der Mine lagerten. Ich denke, sie werden uns dennoch sehr weiterhelfen.\n\nVielen Dank, {name}. Eure Anstrengungen sind lebenswichtig für die Versorgung unserer Streitkräfte.", sourceObjectiveStatus = "unverified-source-field" }
quests[57322] = { id = 57322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Eisenschachtmine", description = "Die Zwerge der Sturmlanzen benutzen die Eisenschachtmine als ein Vorratslager. Ich möchte, dass Ihr diese Mine überfallt und mir ihre Vorräte bringt. Dies sollte die Bemühungen der Sturmlanzen im Alteractal behindern und uns mit der nötigen Ausrüstung versorgen!\n\nSeid vorsichtig, {name}. Die Eisenschachtmine liegt tief im Territorium der Allianz, und die Kontrolle über die Mine ändert sich so oft wie neuer Schnee in Alterac fällt.", sourceObjective = "Bringt 10 Vorräte der Eisenschachtmine zum Rüstmeister der Horde in die Burg Frostwolf.", progress = "Wart Ihr in der Eisenschachtmine, {name}? Habt Ihr die Vorräte geplündert?", completion = "Ihr habt sie! Gute Arbeit, {name}! Hoffentlich habt Ihr unterwegs noch ein paar Zwerge getroffen und ihr Blut im Namen der Frostwölfe vergossen!", sourceObjectiveStatus = "unverified-source-field" }
quests[57323] = { id = 57323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlangenbindung" }
quests[57324] = { id = 57324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit der Flut segeln", sourceObjective = "Trefft Euch mit Calia Menethil und Derek Prachtmeer.", completion = "Mein Tod scheint mir einen neuen Sinn gegeben zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[57326] = { id = 57326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Profitprototypen", description = "<Gazlowe nimmt Euch zur Seite und flüstert.>\n\nSperrt mal die Lauscher auf, {name}. Vor dem Prinzen sollte ich besser 'ne weiße Weste bewahren.\n\nAber ich kann mich doch hoffentlich darauf verlassen, dass Ihr wisst, was außerhalb der Stadt zu tun ist.\n\nAußerhalb der Stadt... wo all die Technologie rumliegt...\n\nTechnologie, die diese Allianzwürmer in ihre Wurstfinger bekommen wollen...\nTechnologie, die wir für die Horde brauchen könnten...\nUm große Waffen damit zu bauen...\nUnd fiese Roboter...\nUnd andere lukrative Produkte...\n\nIhr seid im Bilde, oder?", sourceObjective = "Sammelt bei aktivem Kriegsmodus 150 Implantatprototypen in Mechagon.", progress = "Hier wimmelt's vor Technologie. Wollen wir wetten, dass Ihr hier überall Prototypen finden könnt?", completion = "<Gazlowe durchstöbert die Prototypen, die Ihr gesammelt habt.>\n\nDa ist einiges dabei, {name}... Aus denen können wir ordentlich was machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57327] = { id = 57327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prototypen als Inspiration", description = "<Oberfunks nimmt Euch zur Seite und flüstert.>\n\nAls Leiter dieser geschichtsträchtigen Expedition muss ich an Prinz Erazmins Seite bleiben, um sicherzustellen, dass er nicht von diesem Hordevandalen aufs Kreuz gelegt wird.\n\nIch darf meine Forschung aber nicht vernachlässigen, sonst gewinnt die Horde einen Vorsprung!\n\nUnterlinge wie Ihr müssen daher die Technologieproben sammeln, die der Treibstoff für meine legendären Einfälle sind.\n\nBringt mir Prototypen von dieser Insel und ich verwandle sie in bahnbrechende Erfindungen für die Allianz.", sourceObjective = "Sammelt bei aktivem Kriegsmodus 150 Implantatprototypen in Mechagon.", progress = "Es ist mir einerlei, woher die Prototypen stammen. Nehmt sie Gazlowes Einfaltspinseln ab, wenn Ihr müsst.", completion = "<Der Tüftlermeister sichtet die Prototypen, die Ihr gesammelt habt.>\n\nInteressant... provokativ... inspirierend! Daraus kann ich ganz sicher etwas Nützliches machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57328] = { id = 57328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lager verwüsten" }
