quests[57359] = { id = 57359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschwörungsritual" }
quests[57362] = { id = 57362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefer in die Finsternis", description = "Diese neue Entwicklung ermöglicht es uns, weiter zu erforschen, welche Dunkelheit jenseits der Sande liegen mag.\n\nEs wird nicht einfach werden, {name}. Wir befinden uns am Rande des Unbekannten, aber das Blatt hat sich gewendet.\n\n<Furorion betrachtet Eure neue Kleidung.>\n\nIhr seid dem Anlass entsprechend gekleidet.\n\nSchauen wir mal, welche Erkenntnisse Eure Rückkehr in die Hallen des Ursprungs zutage bringt.", sourceObjective = "Sprecht mit MUTTER, um in die Hallen des Ursprungs in Uldum zurückzukehren und die Quelle der Anomalie zu entdecken.", completion = "Das Entfernen der Verderbnis aus den Hallen des Ursprungs hat N'Zoth veranlasst, seine Aufmerksamkeit neu auszurichten. Die Angriffe auf Uldum und das Tal der Ewigen Blüten werden heftiger.", sourceObjectiveStatus = "unverified-source-field" }
quests[57370] = { id = 57370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff: Das Schwarze Imperium" }
quests[57371] = { id = 57371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff: Ausgegrabene Aqir" }
quests[57372] = { id = 57372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gasse" }
quests[57373] = { id = 57373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abstieg in den Wahnsinn", description = "So schlimm die Ausbreitung der Verderbnis auch anmuten mag, ich bin davon überzeugt, sie bietet uns die Gelegenheit, uns auf die anstehenden Herausforderungen vorzubereiten.\n\nFindet einen der Orte ihres Eindringens und versucht, einen Blick hinter den dunklen Schleier zu werfen.", sourceObjective = "Sucht eine Vision von N'Zoth in der Verderbnis des Tals der Ewigen Blüten oder Uldums auf. Entdeckt dort, was die Zukunft für Azeroth bereithält.", completion = "Ich finde, es ist Zeit, dass wir dieses neue Wissen sinnvoll einsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57374] = { id = 57374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dunkelsten Abgründe", description = "Wo unsere Verbindung nun gesichert ist, sollten wir den Schleier durchbrechen und herausfinden, was dahinter liegt.\n\nEure Entdeckungen könnten der Schlüssel zu unserem Erfolg sein.", sourceObjective = "Betretet eine verstörende Vision, um herauszufinden, welche finsteren Manifestationen in einer Welt unter N'Zoths Herrschaft warten.", progress = "Eure Erfahrung mit solchen Angelegenheiten ist unschätzbar.", completion = "Ihr wart erfolgreich, aber lasst Euch von dem gerade Gesehenen nicht täuschen. Sogar die Geborgenheit dieser Kammer kann ein falsches Gefühl der Sicherheit erzeugen.\n\nDer Verstand ist leicht manipulierbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[57375] = { id = 57375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pulsierender Hügel" }
quests[57376] = { id = 57376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das verborgene Bedürfnis", description = "Wegen Sylvanas stehen einige Mitglieder der Horde den Verlassenen misstrauisch gegenüber. Wir müssen ihr Vertrauen zurückgewinnen.\n\nDas werden wir nicht erreichen, wenn wir uns nicht selbst akzeptieren. So viele fühlen sich verloren... alleingelassen.\n\nIch habe ein Treffen vereinbart. Das könnte ein großer Schritt sein... oder es könnte alles furchtbar schiefgehen. In jedem Fall solltet Ihr ihm als <Zeuge/Zeugin> beiwohnen.\n\nWir treffen uns in Tirisfal am Calstonanwesen.", sourceObjective = "Trefft Euch mit Lilian Voss in Tirisfal.", completion = "Calia Menethil und Derek Prachtmeer sind weit gereist, um mit uns zu sprechen. Wir sollten sie nicht länger warten lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57377] = { id = 57377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gereichte Hand", description = "Hier beginnt das Calia-Intro." }
quests[57378] = { id = 57378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überreste einer zerschmetterten Welt", description = "Das durch diese Visionen gewonnene Wissen bietet uns eine einzigartige Gelegenheit, den eigenen Verstand besser vor Verderbnis zu schützen. Zur Fortsetzung unserer Forschungen müssen wir die tieferliegenden Geheimnisse dieser Erfahrungen ergründen.\n\nSucht die Machthaber innerhalb dieser Visionen auf. Solltet Ihr etwas Interessantes herausfinden, zögert nicht, Eure Erkenntnisse zu teilen.\n\nUnterdessen werden MUTTER und ich unsere Forschungen hier in der Kammer fortsetzen.\n\nWir erwarten Eure Rückkehr, {name}.", sourceObjective = "Besorgt eine Ausgabe von \"Der Fluch des Steins\" aus einer verstörenden Vision für Furorion in der Herzkammer.", progress = "Habt Ihr etwas Interessantes gefunden?", completion = "Faszinierend. Da haben wir offenbar eine Menge Arbeit vor uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[57379] = { id = 57379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befallene Jadestatue" }
quests[57380] = { id = 57380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das eigene Todesurteil unterzeichnen", description = "Glutdistrikt nur für Bösewichte!\n\n<Steinkopf sieht Euch mit zusammengekniffenen Augen an und schüttelt den Kopf.>\n\nIhr seht nicht wie andere Bösewichte aus!\n\nBösewichte haben böse Papiere!", sourceObjective = "Fälscht offizielle Dokumente, die Euch in den Glutdistrikt verbannen.", progress = "Bösewichte haben böse Papiere!", completion = "Diese bösen Papiere sehen sehr böse aus...", sourceObjectiveStatus = "unverified-source-field" }
quests[57381] = { id = 57381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die beste Duellantin", description = "<Ein Sterblicher/Eine Sterbliche> in Revendreth. Sieh an, sieh an... Ihr seid wie geschaffen, um bei risikoreichen Abenteuern mit von der Partie zu sein.\n\nIhr dürft mich Nadjia Nebelklinge nennen und ich bin, wenn ich das in aller Bescheidenheit sagen darf, die beste Duellantin, die jemals ein Schwert geführt hat.\n\nDie Falle, in der Ihr mich vorgefunden habt, war eine Lektion, dass man sich immer im Voraus bezahlen lassen sollte. Lasst mich frei und ich stehe Euch mit meinem Schwert so lange zur Verfügung, wie ich Euch interessant finde.\n\nHaben wir eine Übereinkunft?", sourceObjective = "Befreit Nadjia Nebelklinge.", progress = "Dieses gesegnete Eisen sorgt dafür, dass man sich ziemlich steif fühlt.", completion = "DAS hat Spaß gemacht! Ich habe mich seit Jahrhunderten nicht so lebendig gefühlt. An Euch ist alles einfach... anders und belebend.\n\nIch kann Euch weiterhin helfen, bis Ihr bereit seid, den Endmorast zu verlassen, aber dann werden wir uns für eine Weile trennen müssen. Ich muss noch um jemanden kümmern, der mich in einen Käfig gesteckt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[57384] = { id = 57384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Horrende Heilung" }
quests[57386] = { id = 57386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falls Ihr Frieden sucht...", description = "Maldraxxus ist ein Land voller Zwietracht und Konflikt. Doch seine Bewohner sollten trotzdem durch Ehre gebunden sein.\n\nWenn sie diese vergessen haben, könnten sie ihre Streitkräfte über die Bastion hinaus ausrücken lassen.\n\nSeid vorsichtig, denn hinter diesem Tor lauert Gefahr. Dort wartet ein Reich der Helden, aber auch der Schurken.", sourceObjective = "Betretet Maldraxxus.", completion = "Nun? Warum kämpft Ihr nicht da draußen?", sourceObjectiveStatus = "unverified-source-field" }
quests[57390] = { id = 57390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch das Schwert sterben", description = "Was soll das? Ihr tragt keine Farben! Wo ist der Stolz für Euer Haus, <Gladiator/Gladiatorin>?\n\nPah, diese Dürre lässt uns in der Tat nur noch ein mageres Angebot, wenn dies das Beste sein soll, womit Maldraxxus aufwarten kann!\n\nIch erinnere mich an die alten Zeiten. Die stärksten Seelen kamen und wurden zwischen den fünf Häusern aufgeteilt...\n\nWie auch immer. Das Turnier beginnt. Betretet die Arena! Kämpft für den Ruhm!\n\nSo wie Ihr ausseht, haltet Ihr wahrscheinlich nicht lange durch. Ehrt Euren Namen in der Zeit, die Euch noch bleibt.", sourceObjective = "Besiegt 30 Streiter im Theater der Schmerzen.", completion = "Ihr habt überlebt? Nun...\n\nIch gebe zu, das war unerwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[57391] = { id = 57391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekonstruktion von Der Fluch des Steins", description = "Bei meinen Nachforschungen bezüglich Ny'alotha bin ich auf mehrere Verweise auf dieses Buch gestoßen. Es stammt aus der Feder eines Kultisten niederen Ranges und befasst sich mit den \"Lügen der Titanen\" und dem \"Unrecht\", das den Bewohnern Azeroths angetan wurde.\n\nAlles nur wahnwitzige Propaganda, die das Realitätsverständnis des Lesers zu zerlegen versucht.\n\nWie dem auch sei, wir könnten aus dem Studium dieses Buches mehr über die Macht des Alten Gottes erfahren und damit den Umhang mit besserem Schutz gegen sie versehen.\n\nBringt mir so viele Seiten dieses Buches, wie Ihr finden könnt.", sourceObjective = "Sammelt ausgerissene Seiten von \"Der Fluch des Steins\" aus verstörenden Visionen für Furorion in der Herzkammer.", progress = "Was habt Ihr finden können?", completion = "Ausgezeichnete Arbeit. Dieses Buch dürfte sich als äußerst erhellend herausstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57392] = { id = 57392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekonstruktion von Der Fluch des Steins", description = "Bisher ist der Inhalt des Buches gelinde gesagt beunruhigend. Dennoch konnte ich wertvolle Informationen über die Natur von N'Zoths Macht gewinnen. Ich habe auch schon entsprechende Änderungen an Eurem Umhang vorgenommen.\n\nEs bleibt aber noch viel aufzudecken. Sucht also bei Euren Vorstoßen in die Visionen weiterhin nach zusätzlichen Seiten.", sourceObjective = "Sammelt ausgerissene Seiten von \"Der Fluch des Steins\" aus verstörenden Visionen für Furorion in der Herzkammer.", progress = "Dringende Angelegenheiten bedürfen großer Aufmerksamkeit. Wenn es nicht äußerst wichtig ist, muss ich mich um meine Arbeit kümmern.", completion = "Gute Arbeit, wirklich.", sourceObjectiveStatus = "unverified-source-field" }
quests[57393] = { id = 57393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Finsternis durchschreiten", description = "Mittlerweile habt Ihr bemerkt, dass der Schutz Eures Umhangs abnimmt, je tiefer Ihr in diese Visionen vordringt.\n\nUm Eure Resistenz gegen N'Zoths Einfluss weiter auszubauen, müssen wir ein noch besseres Verständnis seiner niederträchtigen Macht erlangen.\n\nSucht nach Wissen bei den Manifestationen tiefer in den Visionen, und wir werden schon bald unsere Antworten haben.", sourceObjective = "Besorgt eine Ausgabe von \"Furcht und Fleisch\" aus einer verstörenden Vision für Furorion in der Herzkammer.", progress = "Die Schatten sind finster und tief.", completion = "Wie seltsam.\n\nGebt mir einen Moment. Ich sehe mir das genau an.", sourceObjectiveStatus = "unverified-source-field" }
quests[57394] = { id = 57394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekonstruktion von Furcht und Fleisch", description = "Ein weiteres Buch von jemandem, der seinen Verstand an N'Zoth verloren hat. Allein der Gedanke daran, welche widerlichen Worte darin auf uns warten, lässt mich erzittern.\n\nAber wenn wir Euren Umhang verstärken wollen, müssen wir das, wovor er Euch beschützen soll, besser verstehen lernen. Seht, ob Ihr nicht die fehlenden Seiten auftreiben könnt, damit wir dieses Buch vervollständigen und uns das Wissen darin zunutze machen können.", sourceObjective = "Sammelt ausgerissene Seiten von \"Furcht und Fleisch\" aus verderbten oder verlorenen Bereichen verstörender Visionen für Furorion in der Herzkammer.", progress = "Die fehlenden Seiten müssen sich tiefer innerhalb dieser Visionen befinden.\n\nDie Zeiten mögen finster und schwierig erscheinen, aber wir dürfen nicht vergessen, dass Zeiten großer Erfolge und Entdeckungen immer noch möglich sind.", completion = "Beharrlichkeit im Angesicht der Finsternis.\n\nUnsere Arbeit geht weiter...", sourceObjectiveStatus = "unverified-source-field" }
quests[57395] = { id = 57395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekonstruktion von Furcht und Fleisch", description = "Anhänger der Alten Götter behaupten felsenfest, dass Fleisch kein Fluch sondern ein Geschenk ist. Dieses Buch sinniert über die angebliche Güte der Alten Götter, uns ein solches Geschenk gemacht zu haben.\n\nNatürlich fehlt jegliche Erwähnung davon, was passiert, wenn ihrer Verderbnis gestattet wird, sich ungezügelt auszubreiten.\n\nSammelt mehr dieser Seiten für mich. So verkommen diese Schriften auch sein mögen, sie zu studieren wird uns ermöglichen, Euren Umhang effektiver zu machen.", sourceObjective = "Sammelt ausgerissene Seiten von \"Furcht und Fleisch\" aus verderbten oder verlorenen Bereichen verstörender Visionen für Furorion in der Herzkammer.", progress = "Habt Ihr mir etwas mitzuteilen?", completion = "Wie ich sehe, habt Ihr weitere Seiten des Buches gefunden. Sehr gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[57396] = { id = 57396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekonstruktion von Furcht und Fleisch", description = "Anhänger der Alten Götter behaupten felsenfest, dass Fleisch kein Fluch sondern ein Geschenk ist. Dieses Buch sinniert über die angebliche Güte der Alten Götter, uns ein solches Geschenk gemacht zu haben.\n\nNatürlich fehlt jegliche Erwähnung davon, was passiert, wenn ihrer Verderbnis gestattet wird, sich ungezügelt auszubreiten.\n\nSammelt mehr dieser Seiten für mich. So verkommen diese Schriften auch sein mögen, sie zu studieren wird uns ermöglichen, Euren Umhang effektiver zu machen.", sourceObjective = "Sammelt ausgerissene Seiten von \"Furcht und Fleisch\" aus verderbten oder verlorenen Bereichen verstörender Visionen für Furorion in der Herzkammer.", progress = "Wir haben fast die Hälfte geschafft, {name}.\n\nHabt Ihr etwas Neues entdeckt?", completion = "Großartig. Unsere Arbeit fügt sich gut zusammen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57397] = { id = 57397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekonstruktion von Furcht und Fleisch", description = "Der vielleicht heimtückischste Aspekt an den Einflüsterungen der Alten Götter ist die Tatsache, dass sie einen winzigen Kern Wahrheit enthalten. Es ist in der Tat schön, die Sonne auf der Haut und den Wind im Haar zu spüren.\n\nAber Ihr habt N'Zoths Visionen auf Euch genommen. Ihr habt gesehen, wohin seine Pläne am Ende hinführen sollen. Der Fluch des Fleisches hat nichts damit zu tun, dass wir das Leben genießen.\n\nSucht weiter nach den Seiten dieses Buches. Es ist fast vollständig.", sourceObjective = "Sammelt ausgerissene Seiten von \"Furcht und Fleisch\" aus verderbten oder verlorenen Bereichen verstörender Visionen für Furorion in der Herzkammer.", progress = "Die Finsternis verharrt.\n\nNiemals übereilt. Niemals schlafend. Geduldig wartend...", completion = "Ah, die letzten Seiten.\n\nIch glaube, wir sind so weit, unsere Bemühungen ein weiteres Mal voranzutreiben, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[57398] = { id = 57398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Finsternis wandeln", description = "Das Ende naht. Die finstersten Winkel dieser Visionen warten.\n\nUnsere Arbeit hat dafür gesorgt, dass Ihr bestens gerüstet seid, um die verstörendsten Manifestationen aufzusuchen, die diese Visionen aufbieten können. Die endgültigen Antworten liegen direkt dahinter. Unsere Vorbereitungen für Ny'alotha sind beinahe abgeschlossen.", sourceObjective = "Besorgt eine Ausgabe von \"Die Endgültige Wahrheit\" aus verlorenen Bereichen verstörender Visionen für Furorion in der Herzkammer.", progress = "Ich erwarte Eure Rückkehr.", completion = "Ihr solltet dankbar sein, dass Eure Augen nicht auf diese Seiten starren müssen.\n\nJetzt, da sich die letzten Stücke einfügen, beginnen wir mit unseren Vorbereitungen für Ny'alotha.", sourceObjectiveStatus = "unverified-source-field" }
quests[57399] = { id = 57399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekonstruktion von Die Endgültige Wahrheit", description = "Von diesem Buch habe ich gehört. Den Jüngern der Alten Götter ist es heilig, da es die tiefsten Geheimnisse und unbegreiflichsten Mysterien der Leere enthält. Nur den ergebensten Kultisten ist es gestattet, seine Seiten aufzuschlagen.\n\nEs zu halten – selbst in seinem unvollständigen Zustand – jagt mir kalte Schauer über den Rücken. Ich muss vorsichtig sein und nicht zu viel auf einmal lesen.\n\nDennoch müssen wir die fehlenden Seiten ausfindig machen, damit unsere Nachforschungen voranschreiten können. Sucht in den dunkelsten Winkeln von N'Zoths Visionen nach ihnen.", sourceObjective = "Sammelt ausgerissene Seiten von \"Die Endgültige Wahrheit\" aus verlorenen Bereichen verstörender Visionen für Furorion in der Herzkammer.", progress = "Oftmals ertappe ich mich dabei, dass meine Gedanken angesichts dessen, was vor uns liegt, sorgenvoll abschweifen.\n\nWie ergeht es Euch, {name}? Habt Ihr irgendwelche Neuigkeiten?", completion = "Ein weiteres Stück fügt sich ein. Wir sind so nah dran, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[57400] = { id = 57400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekonstruktion von Die Endgültige Wahrheit", description = "Ich wage es nicht, die Schrecken auszusprechen, die diese Seiten festhalten. Die Wörter auf den Seiten scheinen sich beim Lesen zu bewegen, als trachte das Buch selbst danach, einen in den Wahnsinn zu treiben.\n\nDiese Arbeit fordert mir alles ab, aber sie ist notwendig, wenn wir Euch den Gefahren Ny'alothas gefeit machen wollen. Denn so verstörend sämtliche Beschreibungen der Stadt sein mögen, sie zu betreten wird sich als eine noch viel gewaltigere Herausforderung erweisen.\n\nHaltet weiter Ausschau nach Seiten aus dem Buch, {name}. Aber das Lesen... das überlasst Ihr besser mir.", sourceObjective = "Sammelt ausgerissene Seiten von \"Die Endgültige Wahrheit\" aus verlorenen Bereichen verstörender Visionen für Furorion in der Herzkammer.", progress = "Euer Erfolg hat uns bis hierher geführt, {name}. Habt Ihr mir vielleicht etwas mitzuteilen?", completion = "Das Ende unserer Reise rückt näher. Die Finsternis zieht herauf.", sourceObjectiveStatus = "unverified-source-field" }
quests[57401] = { id = 57401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekonstruktion von Die Endgültige Wahrheit", description = "Lang und breit habe ich die Geheimnisse der Alten Götter studiert. Ich habe ganz Azeroth bereist auf der Suche nach esoterischen Texten, verschollenen Archiven und verbotenem Wissen, nur um uns auf den drohenden Schrecken vorzubereiten.\n\nHätte ich auch noch Jahrzehnte mit weiteren Nachforschungen verbracht, nichts hätte mich auf das Ausmaß an Wahnsinn in diesem Buch vorbereiten können. Ein Wahnsinn von solcher Tiefe, dass er sich nur auf Shath'yar ausdrücken lässt.\n\nTreibt mir die letzten Seiten dieses verfluchten Buches auf, {name}. Ich will in Erfahrung bringen, was es mir verraten kann, und es danach nie wieder sehen.", sourceObjective = "Sammelt ausgerissene Seiten von \"Die Endgültige Wahrheit\" aus verlorenen Bereichen verstörender Visionen für Furorion in der Herzkammer.", progress = "Wir sind umgeben von dem Geflüster Ny'alothas. Ich glaube, dass Ihr für die letzte Aufgabe bereit seid, nicht wahr?", completion = "Die Werke sind vollständig. Zusammen erzählen sie vom Abstieg in den absoluten Wahn. Wie ein Trugschluss zum nächsten führt, bis der Realität selbst nur noch Verachtung entgegengebracht wird. Von \"Wahrheit\" fehlt hier jede Spur.\n\nIhr solltet nicht länger das Bedürfnis verspüren, vor den Stimmen davonzulaufen, {name}. Ihr seid bereit, sie zum Schweigen zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57402] = { id = 57402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekonstruktion von Der Fluch des Steins", description = "Wenn N'Zoth eins ist, dann vorsichtig und verschlagen. Ich kann nachvollziehen, wie sich ein leicht zu beeindruckender Verstand mit diesen Schriften gegen die Titanen kehren ließe. Zum Glück sind wir nicht so leicht zu beeindrucken, nicht wahr?\n\nDas Buch ist fast fertig. Sucht in den Visionen weiter nach den verbleibenden Seiten.", sourceObjective = "Sammelt ausgerissene Seiten von \"Der Fluch des Steins\" aus verstörenden Visionen für Furorion in der Herzkammer.", progress = "Ich glaube, wir stehen an der Schwelle von etwas Großem.", completion = "Sehr gute Arbeit, {name}.\n\nEs wird Zeit, dass wir unsere Bemühungen vorantreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[57403] = { id = 57403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekonstruktion von Furcht und Fleisch", description = "Der vielleicht heimtückischste Aspekt an den Einflüsterungen der Alten Götter ist die Tatsache, dass sie einen winzigen Kern Wahrheit enthalten. Es ist in der Tat schön, die Sonne auf der Haut und den Wind im Haar zu spüren.\n\nAber Ihr habt N'Zoths Visionen auf Euch genommen. Ihr habt gesehen, wohin seine Pläne am Ende hinführen sollen. Der Fluch des Fleisches hat nichts damit zu tun, dass wir das Leben genießen.\n\nSucht weiter nach den Seiten dieses Buches. Es ist fast vollständig.", sourceObjective = "Sammelt ausgerissene Seiten von \"Furcht und Fleisch\" aus verderbten oder verlorenen Bereichen verstörender Visionen für Furorion in der Herzkammer.", progress = "Macht Ihr Fortschritte?", completion = "Die Schriften in diesem Buch bauen auf denen aus dem Buch, das wir bereits vervollständigt haben, auf und vertiefen sie.\n\nMacht so weiter, {name}. Ich gehe davon aus, dass wir sehr bald Antworten haben werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[57404] = { id = 57404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verheererbau" }
quests[57405] = { id = 57405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Wahnsinn jagen", description = "<Diese Venthyr ist in erbärmlichem Zustand. Sie murmelt unkontrolliert vor sich hin und kratzt am Boden.\n\nPlötzlich sieht sie hoch und zeigt mit dem Finger auf Euch.>\n\nHat ein Gegner keine Fähre, würd' er nicht froh, wenn man nicht achtsam wäre!\n\n<Sie scheint auf eine Antwort von Euch zu warten.>", sourceObjective = "Findet heraus, was die Verlorene Sibylle Euch zeigen will.", completion = "Na, wenn Ihr kein unerwarteter Glücksfall seid!\n\nIch fürchte, ich habe keinen Tee, den ich Euch im Moment anbieten könnte. Verzeiht meine schlechten Manieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[57414] = { id = 57414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mount Up Test" }
quests[57425] = { id = 57425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Land der Möglichkeiten", description = "<Die Stimme des Großmeisters erklingt über der tosenden Menge.>\n\nDas ist es! Das Finale des Turniers!\n\nDiese beiden maldraxxischen Gladiatoren haben Herausforderer nach Herausforderer zur Strecke gebracht! Das einzige, was nun verbleibt ist...\n\nDass sie sich gegenseitig umbringen!", sourceObjective = "Besiegt den Obersten Champion Meskal.", completion = "In grauer Vorzeit hat der Primus das Turnier ins Leben gerufen, um die Macht von Maldraxxus zu demonstrieren. \n\nHeute hat es einen erbitterten Krieg entzündet.", sourceObjectiveStatus = "unverified-source-field" }
quests[57426] = { id = 57426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein schrecklicher Morgen", description = "Ihr werdet nicht glauben, was mir widerfahren ist!\n\nIch war auf meinem täglichen Spaziergang, als Marquis Fausthagel und seine Rüpelbande mich attackiert haben!\n\nBei all dem bedauerlichen und ungebührlichen Gebaren, das sie den an den Tag legten, haben sie auch meinen Sonnenschirm zerstört.\n\nEine Tragödie höchsten Ausmaßes!\n\nOhne ihn bin ich dem verfluchten Licht, das auf diesem Land lastet, schutzlos ausgesetzt.\n\nDer Marquis nennt ein verborgenes, schattiges Versteck in der Nähe sein Eigen. Würdet Ihr meinen Sonnenschirm rächen und diesem Rüpel Manieren beibringen?", sourceObjective = "Tötet Marquis Fausthagel.", completion = "<Dem Licht ausgesetzt zu sein, lässt Theotar offensichtlich die Kontrolle über sich verlieren.>\n\nGerechtigkeit... für Sonnenschirme... überall...", sourceObjectiveStatus = "unverified-source-field" }
quests[57427] = { id = 57427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unerträgliches Licht", description = "Seid Ihr schon einmal einem Ascheghul begegnet? Die erbärmlichen Kreaturen kriechen über den Boden. Springen auf alles drauf. Fürchterliche Tischmanieren.\n\nDieses unglückselige Schicksal erwartet alle Venthyr, die dem Licht zu lange ausgesetzt sind. Der überwältigende Schmerz, den es verursacht, bricht unsere Entschlossenheit, unseren Verstand und letztendlich auch unseren Körper.\n\nMit den richtigen Fertigkeiten ist es möglich, den Verfall durch das Licht umzukehren, aber nur, wenn er schnell behandelt wird.\n\nFür die Ascheghule in diesem durch das Licht versengten Krater gibt es allerdings keine Erlösung mehr. Man kann ihnen nur noch auf eine Art Gnade erweisen.", sourceObjective = "Tötet 12 Ascheghule.", progress = "Wenn ich ihnen doch nur früher schon hätte helfen können...", completion = "<Dem Licht ausgesetzt zu sein, lässt Theotar offensichtlich die Kontrolle über sich verlieren.>\n\nMeine... aufrichtige Entschuldigung...", sourceObjectiveStatus = "unverified-source-field" }
quests[57428] = { id = 57428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Theotars Mission", description = "Oh, die Anklägerin schickt Euch? Wie verwegen!\n\nMir ist das Schicksal von Prinz Renathal tatsächlich bekannt... zumindest teilweise.\n\nAls unser Angriff auf die Burg des Meisters fehlschlug, wurden wir beide gefangen genommen. Ich wurde in den Glutdistrikt verbannt, aber den Prinzen hat man nach Sündensturz verschleppt.\n\nIch arbeite an einem Fluchtplan aus diesem lichtverseuchten Land, um ihm zu folgen, aber das Licht hier... erschwert das Denken ungemein.\n\nFrüher hat mich mein Sonnenschirm geschützt, aber diese Rüpel haben ihn zerstört. Helft mir, ihn wiederherzustellen, und wir werden den Prinzen gemeinsam finden.", sourceObjective = "Sammelt 8 versengte Planken und 8 majestätische Stofffetzen.", progress = "Meine Lieblingsfarben sind pink und weiß, wenn Ihr sie finden könnt.", completion = "<Dem Licht ausgesetzt zu sein, lässt Theotar offensichtlich die Kontrolle über sich verlieren.>\n\nGubbins... Wo bist du?", sourceObjectiveStatus = "unverified-source-field" }
quests[57429] = { id = 57429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scheiterhaufen des Amalgamierten" }
quests[57442] = { id = 57442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verloren in der Austrocknung", description = "<Dem Licht ausgesetzt zu sein, hat dazu geführt, dass Theotar keine schlüssigen Sätze mehr bilden kann.\n\nStatt Euch zu sagen, wie Ihr sein Versteck erreicht, murmelt er zusammenhangslos und zeigt in zufällige Richtungen.>\n\nVerirrt... Syb... Tubbins... Zu spät zum Tee...\n\n<Ihr müsst Theotars Versteck auf andere Weise finden.>", sourceObjective = "Findet den Weg zu Theotars Versteck.", completion = "<Gubbins und Tubbins sprechen wie aus einem Mund.>\n\nDas ist nicht gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[57443] = { id = 57443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drecksarbeit: Abrisstrupp" }
quests[57444] = { id = 57444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inspiration zur moralischen Bestandsaufnahme", description = "{name}! Ihr seid wohlauf! Wie schön.\n\nViele der Aufgestiegen, die einst an diesen Ort kamen, um zu dienen, haben uns verraten. Sich voll und ganz von allem abzuwenden, für das die Kyrianer stehen, ist... einfach unvorstellbar.\n\n<Der Akolyth legt einen schweren Speer in Eure Hände.>\n\nDieses Werkzeug kam bis heute nur selten zum Einsatz. Sein einziger Zweck besteht darin, jene, die er berührt, zu einem Moment der Reflexion zu inspirieren und ihnen so vor Augen zu führen, dass sie vom rechten Weg abgekommen sind.\n\nSollten sie aber weiter an ihrem Irrweg festhalten, ist alle Hoffnung für sie verloren. Dann müssen sie sterben.", sourceObjective = "Tötet 3 Aufgestiegene der Verschmähten.", progress = "Sie haben uns verraten.", completion = "Ich habe ihr Ende gesehen. Das ist mehr, als sie verdient haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[57445] = { id = 57445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chins Nudelwagen" }
quests[57446] = { id = 57446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vertraute Feind", description = "Mein Herz ist voller Angst. Wenn es wirklich Lysonia ist, die sie jetzt anführt...\n\nNein. Wichtig ist, dass wir die großen Vesperglocken wiederherstellen. Solange ihre mächtigen Stimmen verderbt sind, werden alle, die sie hören, genauso leiden wie dieser Tempel. Es ist nur eine Frage der Zeit, bevor die ganze Bastion unterliegt.\n\nZweifellos werden sie versuchen, Euch aufzuhalten. Ich werde ihren Anführer so lange wie möglich ablenken.\n\nSollte ich nicht überleben... Mein Jünger wird Euch wohlbehalten von hier wegbringen. Geht und dient.", sourceObjective = "Stellt Lysonia und läutert die großen Vesperglocken.", completion = "Unser Kampf ist noch nicht vorbei, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[57447] = { id = 57447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinheit geht vor", description = "Spürt Ihr das, {name}?\n\nDie kalte Hand, die sich um Euren Hals schließt? Das Flattern in der Magengegend? Es ist die Berührung des Schlunds, das ist so sicher wie der Wille der Archon.\n\nIch weiß nicht, wie Lysonia diese Macht erlangt hat, doch wir müssen uns beeilen.\n\nIch werde die Archon darüber in Kenntnis setzen, was sich hier zugetragen hat. Ihr werdet handeln, wo meine Hand es nicht konnte. Ich erkläre es Euch unterwegs.\n\nSprecht mit mir, wenn Ihr bereit seid, den Tempel zu verlassen.", sourceObjective = "Fliegt mit Vesiphone zur Reflexion der Reinheit.", completion = "Uns ist heute keine ruhige Minute vergönnt, oder?\n\n<Kleia richtet einen argwöhnischen Blick auf das Fragment.>", sourceObjectiveStatus = "unverified-source-field" }
quests[57448] = { id = 57448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Verbündete unter uns", description = "Sogar in Friedenszeiten hat die Horde ihre Probleme.\n\nObwohl unsere Machtkämpfe manchmal erdrückend sein können, so sollten sie uns nicht davon abhalten, uns ins Gedächtnis zu rufen, was es heißt, Teil der Horde zu sein.\n\nWir schicken niemanden fort, wenn harte Zeiten anbrechen. Wir stehen sie gemeinsam durch.\n\nEinen Moment lang ist mir das entfallen. Ich war durch die Sorgen, die unsere neuen Verbündeten mitbrachten, so belastet, dass ich voreilig die Vulpera abgewiesen habe.\n\nIch kann nur hoffen, dass sie der Horde immer noch so viel Wert beimessen wie ich ihnen.", sourceObjective = "Erlebt mit, wie Baine die Vulpera in die Horde aufnimmt.", completion = "Vulpera in der Horde. Eine zweckmäßige Partnerschaft, findet Ihr nicht? Ohne Eure Hilfe wäre sie nicht möglich gewesen.\n\nDank Euch, {name}, haben wir jetzt eine Heimat jenseits der Dünen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57449] = { id = 57449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exekutor von N'Zoth" }
quests[57453] = { id = 57453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarmrufer" }
quests[57454] = { id = 57454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stille der Stiele", description = "Hmm. Also, das ist nicht... gut. Aber noch gibt es keinen Grund zur Panik!\n\nEs ist lange her, seit sich unser Ring von hier zurückgezogen hat, und wir müssen wahrscheinlich an seinen Ursprung gelangen, um ihn zur Rückkehr zu bewegen!\n\nLeider habe ich seit Beginn der Krise nichts mehr von unserem Obersten Pilzomanten Cortinarius gehört.\n\nBitte findet ihn und helft uns, die Verbindung zu den Ringen wiederherzustellen! Begebt Euch zu den Stielen westlich von Traumsang Fenn. Wenn Ihr den Pilzen folgt, könnt Ihr sie nicht verfehlen!", sourceObjective = "Sprecht mit Cortinarius außerhalb der Stiele.", completion = "Endlich ein freundliches Gesicht! Gehört Ihr zur Jagd? Ihr seht nicht so aus, als ob Ihr aus dieser Gegend stammt...", sourceObjectiveStatus = "unverified-source-field" }
quests[57455] = { id = 57455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kompostierung", description = "Die Pilze werden angegriffen! Ich brauche Eure Hilfe oder wir laufen Gefahr, alles zu verlieren!\n\nEinige Fae mit merkwürdigen Masken sind hier aufgetaucht und haben Zugang zu den Ringen verlangt. Als ich ihnen gesagt habe, sie seien wegen der Dürre geschlossen, haben sie mich einfach angegriffen!\n\nIch bin zu schwach, um mich jetzt zu wehren, und außerdem vom mittleren Ring abgeschnitten. Diese Fae haben so viel zerstört, aber wir können etwas tun.\n\nStreut ein paar dieser Sporen über einige ihrer Leichen, um die Ringe wieder wachsen zu lassen. Sogar im Tod können unsere Feinde dem Ardenwald noch dienen.", sourceObjective = "Verwendet den Beutel mit Sporen, um Pilze auf 15 maskierten Fae in den Stielen zu pflanzen.", progress = "Sie würden so oder so die Pilze nähren, also könnt Ihr den Prozess ruhig beschleunigen.", completion = "Ihre Körper werden das Wachstum und die Wiederherstellung der Faeringe vorantreiben. Das ist ein würdiges Ende für sie.", sourceObjectiveStatus = "unverified-source-field" }
quests[57456] = { id = 57456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geisttrinker" }
quests[57457] = { id = 57457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shaking 'Shrooms" }
quests[57458] = { id = 57458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ringheilung", description = "Der hier verursachte Schaden ist immens, aber er kann rückgängig gemacht werden.\n\nMein Meister ist geschwächt von all der Zerstörung, aber Pilze kann man nur schwerlich ausmerzen. Wenn wir die Ringe überall im Hain erneut mit Energie versorgen, können wir sie wieder erstarken lassen.\n\nNehmt dieses Leuchtfeuer. Verwendet es in der Nähe eines beschädigten Pilzes in einem Ring und beobachtet, wie schnell die Natur ihre Wunden heilen kann.", sourceObjective = "Benutzt das Fungusleuchtfeuer, um 6 beschädigte Pilze zu heilen.", completion = "Gemeinsam sind wir stark.", sourceObjectiveStatus = "unverified-source-field" }
quests[57459] = { id = 57459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fungusverteidigung", description = "Sehet... Marasmius!\n\nDies ist sein Heim, sein Herz. Jeder Pilz im Ardenwald, vielleicht sogar in den gesamten Schattenlanden, ist von hier entsprungen. Und die maskierten Fae wollen ihn für ihre eigenen Zwecke entwenden. Als oberster Pilzomant kann ich das nicht dulden.\n\nUnsere Feinde mögen geistlos erscheinen, aber sie sind schlau. Sie werden mich inzwischen aufgespürt haben.\n\nIch werde hier mein letztes Gefecht bestreiten und darauf hoffen, dass Marasmius stark genug ist, seine Unterstützung zu gewähren.\n\nWerdet Ihr mir beistehen, {class}?", sourceObjective = "Helft Cortinarius bei der Verteidigung von Marasmius.", completion = "<Wurde auch Zeit, dass Ihr auftaucht! Wie gut, dass ich mich um den Nachwuchs gekümmert habe, nicht wahr?>", sourceObjectiveStatus = "unverified-source-field" }
quests[57460] = { id = 57460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tubbins' Tee", description = "Theotar hat Tubbins besonderen Tee beigebracht, der Licht verschwinden lässt!\n\nTubbins ist ein guter Teemacher!\n\nSeht zu, wie Tubbins macht, dass Theotar sich wieder gut fühlt!\n\nDann fühlt Tubbins sich gut!", sourceObjective = "Helft Tubbins dabei, den besonderen Tee zuzubereiten, der Theotar heilen soll.", completion = "Tee ist fertig! Tubbins gibt ihn Theotar!", sourceObjectiveStatus = "unverified-source-field" }
quests[57461] = { id = 57461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ereignisloser Spaziergang", description = "Ich hoffe, ich war unter dem Einfluss des Lichts nicht allzu unhöflich. Ich bemühe mich, mich zusammenzunehmen, aber der Schmerz, den es verursacht... macht einen wahnsinnig.\n\nWie dem auch sei, der Tee hat meine Lebensgeister wieder geweckt!\n\nAls ich Prinz Renathal das letzte Mal gesehen habe, hat der Meister ihn in den großen Turm verschleppt, der über dem Glutdistrikt aufragt.\n\nIch selbst und einige andere haben daran gearbeitet, von unten her Zugang zum Turm zu erlangen, aber es gibt... Hindernisse.\n\nWenn Ihr bereit zum Aufbruch seid, führe ich Euch in unser sogenanntes Hauptquartier, das Refugium des Wahnsinnigen.", sourceObjective = "Eskortiert Theotar zum Refugium des Wahnsinnigen.", completion = "<Theotar nimmt gemächlich einen Schluck Tee.>\n\nWas für ein wundervoller Spaziergang!", sourceObjectiveStatus = "unverified-source-field" }
quests[57462] = { id = 57462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traumfänger", description = "Der Fokus scheint stabil und das Eindämmungsfeld ist unversehrt. Ich möchte meinen, wir könnten ihn noch weiter ermächtigen.\n\nMacht Jagd auf herausfordernde Gegner und besiegt sie, um zusätzliche Überreste von N'Zoths Einfluss zu sammeln. Dieses Mal werden wir den Fokus mit noch mehr der Macht des Alten Gottes erfüllen. Ich bin zuversichtlich, dass das Eindämmungsfeld weiter halten wird.", sourceObjective = "Beschafft 200 Wahnsinnsfetzen. Ihr könnt sie von Bossen in Ny'alotha und Weltbossen, durch Siege auf Schlachtfeldern und in Arenen oder durch ehrenhafte Siege erhalten.", progress = "Dem Mutigen gehört die Welt, {name}. Und kaum etwas ist mutiger, als die Macht eines Alten Gottes zu nutzen.", completion = "Gut gemacht, {name}.\n\nSobald wir den Fokus mit dieser Macht erfüllt haben, könnt ihr die teuflischsten Gegenstände erschaffen, die N'Zoths verdrehtem Verstand entspringen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[57463] = { id = 57463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legt Euch nie mit Pilzen an", description = "<Eine alte, donnernde Stimme erfüllt Euren Verstand.>\n\nHmpf. Es kommen noch mehr.\n\nIch würde lieber nicht noch mehr von mir verlieren. Und ich will auch nicht, dass Ihr und Cort glaubt, ich wäre Euch nicht dankbar für Eure Taten.\n\nBegebt Euch doch auf eine Runde durch meine Ringe und verpasst den Trotteln ein wenig Prügel. Die werden noch lernen, dass man sich nicht mit Marasmius und seinen Faeringen anlegt!", sourceObjective = "Reist durch die Faeringe mit Marasmius und besiegt 30 Eindringlinge.", completion = "Ha! So jung habe ich mich schon seit Ewigkeiten nicht mehr gefühlt!", sourceObjectiveStatus = "unverified-source-field" }
quests[57464] = { id = 57464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Fokus bewahren", description = "Bis jetzt enthält der Fokus nur einen kleinen Teil der wahren Macht von N'Zoth. Wenn wir ihn weiter ermächtigen würden, könnten wir noch mächtigere Waffen schaffen, die wir gegen ihn einsetzen können.\n\nN'Zoths Einfluss ist überall, {name}, und besonders stark ist er bei mächtigen Feinden. Bezwingt sie und entreißt ihnen die Überreste der Macht des Alten Gottes.", sourceObjective = "Beschafft 20 Wahnsinnsfetzen. Ihr könnt sie von Bossen in Ny'alotha und Weltbossen, durch Siege auf Schlachtfeldern und in Arenen oder durch ehrenhafte Siege erhalten.", progress = "Wir wagen hier einen gefährlichen Schachzug, {name}. Vorsicht ist dabei von höchster Bedeutung.", completion = "Ausgezeichnet. Die sollten genau das bieten, was wir brauchen.\n\nIch werde den Gegenständen die Verderbnis entziehen und in den Fokus umlenken. Danach könnt Ihr damit noch mächtigere Gegenstände erschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57465] = { id = 57465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drecksarbeit: Holzarbeiten" }
quests[57470] = { id = 57470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine monströse Entdeckung", sourceObjective = "Folgt Draka zu Gharmals Turm.", completion = "Gharmals Maßlosigkeit kannte keine Grenzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57471] = { id = 57471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echte Drecksarbeit", description = "Diese Schlammlache ist vollkommen unbrauchbar. Der Animamangel hat hier zweifellos seinen Tribut gefordert.\n\nWisst Ihr, die Lachen benötigen Dreck und Fasern, damit darin brauchbare Gräber heranwachsen können. Das Problem ist... jedes Mal, wenn ich versuche, die Lache zu behandeln, habe ich diese verflixten Verschlinger am Hals!\n\nJetzt fängt der unbehandelte Schlamm an, sich zu diesen Elementaren zusammenzuballen! Könnt Ihr helfen und etwas von diesem schmutzigen Schutt in die Lache werfen, um sie wiederherzustellen?", sourceObjective = "Werft schmutzigen Schutt in die Schlammlache.", completion = "Ich kann es von hier aus riechen! Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[57473] = { id = 57473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wertvollster Besitz", description = "Diese Truhe ist anders. Sie ist größer als die anderen... und was noch wichtiger ist, sie ist verschlossen.\n\n<Mograine zerschlägt das Schloss.>\n\nNa, dann sehen wir mal, was drin ist.", sourceObjective = "Öffnet die verzierte Truhe.", progress = "Wie haben sie das erhalten?", completion = "Der Mantel des Primus...\n\nDas Schicksal ist uns heute wohlgesonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57474] = { id = 57474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gräberpflicht", description = "Mit der Schlammlache ist wieder alles bestens. Das reicht für ein paar Gräber, aber die Verschlinger machen immer noch Ärger.\n\nWir brauchen einen Edelstein der Bindung. Damit können wir einen großen Lulatsch ausgraben, der die Lache beschützt.\n\nIch zeige Euch, wie Ihr erst mal ein paar entbehrliche Gräber ausgrabt.\n\nLasst sie in den Trümmern nach dem Edelstein der Bindung graben. Dann machen wir aus dem Haufen einen Lulatsch, dann ist Schluss mit den Verschlingern!", sourceObjective = "Grabt einen Gräber aus und bringt ihn zu dem Schutthaufen. Wartet, bis er sich durch den Haufen gegraben hat, und nehmt den Edelstein der Bindung an Euch.", progress = "Habt Ihr den Edelstein?", completion = "Da ist ein bisschen Verschlingerschleim drauf, aber er muss reichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57475] = { id = 57475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der zurückgebrachte Mantel", description = "Der Mantel des Primus...\n\nIch kann es kaum fassen, dass Gharmal ihn hatte. Dass sie ihn nicht gegen uns eingesetzt haben. Dass wir ihn zurückerobert haben.\n\nDies könnte für unsere Bemühungen, Maldraxxus wiederaufzubauen, von größter Bedeutung sein. Wir müssen ihn sofort zu Baronin Draka beim Sitz des Primus zurückbringen.", sourceObjective = "Kehrt zu Draka im Sitz des Primus zurück.", completion = "Ich sende Späher aus, um die Suche fortzuführen, aber das... das bringt uns einen gewaltigen Vorteil.", sourceObjectiveStatus = "unverified-source-field" }
quests[57476] = { id = 57476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdgründe der Vil'thik" }
quests[57477] = { id = 57477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir werden einen größeren Gräber brauchen", description = "Danke, dass Ihr den Stein geholt habt, {name}. Während Ihr unterwegs wart, habe ich noch ein paar von den Jungs ausgegraben.\n\nJetzt müssen wir diese Gräber nur noch in Lulatsche verwandeln.", sourceObjective = "Wohnt dem Ritual bei.", progress = "Was wollt Ihr?", completion = "Bottus bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[57481] = { id = 57481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles einstampfen", description = "Bottus ist bereit, Verschlingerschädel zu zerschmettern.\n\nSpringt auf.", sourceObjective = "Steigt auf Bottus und vereitelt den Einmarsch der Verschlinger.", completion = "Gute Arbeit, {name}.\n\nLulatsche sind manchmal... ein bisschen zu viel des Guten.", sourceObjectiveStatus = "unverified-source-field" }
quests[57484] = { id = 57484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual des Erwachens" }
quests[57486] = { id = 57486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwindende Energie", description = "Mekkadrills Rettungskapsel verliert Energie.\n\nWir hören ihn nicht mehr sprechen.\n\nSein Puls hat sich trotz aller Bemühungen der Heiler von Kul Tiras verlangsamt.\n\nIch habe eine Idee, aber ich werde Eure Hilfe brauchen.\n\nTrefft mich bei Burg Prachtmeer. Wir müssen bald aufbrechen.", sourceObjective = "Trefft Kelsey Stahlfunken bei Burg Prachtmeer.", completion = "Was wir jetzt tun werden, ist vielleicht nicht gerade ein... äh... abgesegneter Plan.\n\nWir werden einfach später um Verzeihung bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[57487] = { id = 57487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jemand, der helfen kann", description = "Ich glaube, es gibt einen Weg, Mekkadrill zu helfen, aber einige werden wohl nicht zu hundert Prozent dahinterstehen...\n\nDie Mechagnome verfügen über fortgeschrittene Technik im Bereich biomechanische Reparaturen und Verbesserungen.\n\nWenn es auch nur den Hauch einer Chance gibt, dass sie ihm helfen können, müssen wir es versuchen! Einige Mechagnome schicken von einem Dock am Hakenkap aus Vorräte hinüber zur Insel. Niemand wird ein zusätzliches Frachtstück bemerken. Wir müssen einen ihrer Frachtkopter umleiten.\n\nWürdet Ihr mir bitte helfen, Mekkadrills Rettungskapsel nach Mechagon zu schaffen?", sourceObjective = "Helft Kelsey, Mekkadrills Rettungskapsel nach Mechagon zu verfrachten.", completion = "Es wäre mir ein Vergnügen, dem äußerst angesehenen Hochtüftler Mekkadrill Hilfe zu gewähren!", sourceObjectiveStatus = "unverified-source-field" }
quests[57488] = { id = 57488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aktueller Bauplan", description = "Ich glaube, ich kann eins unserer bereits existierenden Geräte umfunktionieren, sodass wir Zugang zu Gelbin Mekkadrill bekommen, ohne die lebenserhaltenden Funktionen zu beeinträchtigen.\n\nEs gibt einige Gegenstände, die Ihr besorgen müsst.\n\nAuf dem nahegelegenen Vektor der Halden findet Ihr Schrottbots und Schrotthunde. Diese wären eine feine Ersatzteilquelle für mein Konstruktionsprojekt.\n\nDer Auslass beherbergt einige besonders schleimige Freunde. Sie liefern Euch ausgezeichnete Zutaten für das hitzebeständige Schmiermittel, das wir benötigen.", sourceObjective = "Sammelt 4 hitzebeständigen Schlick und 6 beschaffte Maschinenteile.", progress = "Habt Ihr alle Sachen gefunden?", completion = "Ja, ja, die genügen vollkommen.\n\nAusgezeichnete Arbeit, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[57490] = { id = 57490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise in die Sicherheit", description = "Einer unserer Verteidiger hat beobachtet, wie die Troggs den Frachtkopter mit Mekkadrills Rettungskapsel an Bord abgeschossen haben.\n\nSeit wir begonnen haben, Waren aus Tiragarde herzubringen, sind sie uns nur auf die Nerven gegangen.\n\nKolbert, ein vielversprechender junger Erfinder, hat genau das richtige Fahrzeug für diese Aufgabe. Trefft seine Mannschaft auf Bondos Hof.\n\nBitte beeilt Euch und bergt die Rettungskapsel! Ich bin nicht sicher, was mit Gelbin passieren wird, wenn sie sie aufbrechen.\n\nÄhm, wir hätten übrigens nichts dagegen, wenn Ihr ein bisschen Strandsäuberung betreibt, während Ihr dort seid...", sourceObjective = "Besiegt die plündernden Troggs und bergt Mekkadrills Rettungskapsel.", progress = "Sind alle wieder heil zurückgekommen?", completion = "Ich hoffe, der arme Kerl ist da drin nicht allzu sehr durchgeschüttelt worden.", sourceObjectiveStatus = "unverified-source-field" }
quests[57491] = { id = 57491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besser... stärker... weniger tot", description = "König Mechagon mag ja verrückt gewesen sein, aber seine Diener hatten herausragende Fähigkeiten beim Bau von Robotern.\n\nEin paar übrig gebliebene Kreationen streunen immer noch in Mechagon herum. Sie weigern sich, König Mechagons Entthronung zu akzeptieren.\n\nDie logische Schlussfolgerung einer Niederlage ist der Rückzug, wenn man noch funktionstüchtig ist. Einige sind nicht allzu bewandert, was die Logik angeht.\n\nIm Moment tragen sie das Beste bei sich, was der technische Fortschritt zu bieten hat. Ich glaube, es wäre unserer Bergungsaktion sehr von Nutzen, wenn wir an bestimmte Teile dieser Einheiten herankommen könnten.", sourceObjective = "Beschafft den neuralen Beschleuniger, den elektromagnetischen Omniverstärker und fluxgeladene Servos von den unkontrollierbaren Einheiten.", progress = "Habt Ihr die Ersatzteile besorgt, die wir benötigen?", completion = "Sie haben kaum einen Kratzer abbekommen!\n\nEin paar Aufwertungen und Ihr würdet das in der halben Zeit schaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57492] = { id = 57492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er?", description = "Sprecht mit einigen Gnomen in Mechagon, egal ob sie aufgewertet sind oder nicht. Fragt mein Volk, was sie sich von einem Anführer für unseresgleichen erhoffen. Fragt unsere neuen Freunde, was sie an ihrem aktuellen Anführer am meisten schätzen.\n\nNach dem, was ich bisher erfahren habe, hat der Hochtüftler sein Volk nur deswegen angeführt, weil es nötig war. Er selbst hat nie nach der Krone gegriffen. Ich glaube, die Gnome sollten wieder geeint werden.\n\nIch suche nach einer Lösung, für die alle offen sind. Würdet Ihr die Informationen sammeln, die ich benötige?", sourceObjective = "Sammelt Daten von Gnomen und Mechagnomen in Mechagon.", progress = "Waren Eure Gespräche produktiv?", completion = "Sehr gut, sehr gut, das sind die Ergebnisse, auf die ich gehofft hatte. Ihr habt meine Theorie untermauert.", sourceObjectiveStatus = "unverified-source-field" }
quests[57493] = { id = 57493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mentale Abstimmung", description = "Jetzt haben wir eine Basisreferenz für Mekkadrill und mir scheint, da gibt es Raum für Verbesserungen.\n\nEure Hilfe wird benötigt, um ihn zu stabilisieren und zu synchronisieren, bevor wir ihn aus seiner Kapsel holen.\n\nBitte stellt Euch neben das Synchroskop. Ich nehme die Einstellungen vor, und Ihr müsst die Maschine anwerfen, wenn ich rufe.", sourceObjective = "Aktiviert das Synchroskop, wenn Christy Euch Bescheid sagt.", progress = "Habt Ihr erfolgreich den Knopf gedrückt?", completion = "Eure Fähigkeit, Knöpfe zu drücken, ist lobenswert.\n\nWir haben Glück, dass Ihr hier wart.", sourceObjectiveStatus = "unverified-source-field" }
quests[57494] = { id = 57494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein starkes Herz", description = "Wir haben ein Leuchtfeuer in der Nähe des Schrottwattdepots gesehen.\n\nDas Bergungsteam hat es mit der Energiequelle nach draußen geschafft. Jetzt, da wir endlich sicher vor König Mechagons Annihilo-tron sind, wird sein Herz einem neuen Zweck dienen.\n\nDas sind großartige Neuigkeiten!\n\nDennoch, das Leuchtfeuer bedeutet, dass sie Gesellschaft haben. Eure Hilfe wird nötig sein, um das Team herauszuschleusen und den Funkenreaktor zu bergen.\n\nBitte eilt Euch, wir sind so kurz vor dem Abschluss.", sourceObjective = "Bergt den Funkenreaktor und schließt Mekkadrills Prozedur ab.", progress = "Seid Ihr bereit?", completion = "Ich bin sehr zufrieden.\n\nBei einer 40%igen Erfolgschance war ich nicht sicher, ob die Variablen sich zu Euren Gunsten auflösen würden.\n\nDas war wirklich eine glückliche Verkettung von Ereignissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57495] = { id = 57495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zukunft von Mechagon", description = "Da Mechagon jetzt von den restlichen Gefahren gesäubert wurde, könnte es wieder zu einem Ort des Friedens und Wohlstands für Gnome und Mechagnome gleichermaßen werden.\n\nEs ist Zeit, mit Prinz Erazmin über die Zukunft unserer Völker zu sprechen. Ich hoffe aufrichtig, dass wir ein Bündnis schmieden, das viele Generationen überstehen wird!\n\nWenn Ihr bereit seid, gesellt Euch im Hohen Tüfteltorium für eine ganz besondere Ansprache zu uns.", sourceObjective = "Reist zum Hohen Tüfteltorium in Stadt Mechagon.", completion = "Dies war wahrlich ein glorreicher Tag für Gnome und Mechagnome! Ohne Euch wäre das nicht möglich gewesen, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[57496] = { id = 57496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg", description = "Nach allem, was die Mechagnome heute für uns getan haben, ist es unsere Pflicht, den Gefallen zu erwidern.\n\nLasst uns die abtrünnigen Schöpfungen ausmerzen, die noch in Mechagon verblieben sind.\n\nWenn ihre Heimat wieder ihnen gehört, werden Prinz Erazmin und sein Volk eine rosige Zukunft haben.\n\nMit diesem Team werden wir mit König Mechagons verbliebenen Loyalisten kurzen Prozess machen.\n\nLasst mich wissen, wenn Ihr abmarschbereit seid!", sourceObjective = "Beseitigt die verbliebenen Verteidiger in Mechagon.", completion = "Das war aufregend!\n\nDie Welt ist gerade ein wenig größer geworden!", sourceObjectiveStatus = "unverified-source-field" }
quests[57497] = { id = 57497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbreitet die Neuigkeiten", description = "Wir wollten ein Leben retten und haben so viel mehr erreicht!\n\nOhne Euch hätten wir es wirklich nicht geschafft, {name}. Ich bin so aufgeregt, wenn ich an die Zukunft der Gnomheit denke.\n\nGeht zurück nach Sturmwind und verbreitet die guten Neuigkeiten.", sourceObjective = "Bringt Aysa Wolkensänger in Sturmwind auf den neuesten Stand.", completion = "Hervorragende Ergebnisse, {name}!\n\nIch werde Eure Neuigkeiten mit den Anführern der Allianz teilen.\n\nIch freue mich darauf, ein paar neue Spielzeuge zu sammeln...", sourceObjectiveStatus = "unverified-source-field" }
quests[57506] = { id = 57506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorenes Licht", description = "Einige unserer Aspiranten haben törichterweise geglaubt, dass sie den Schlund betreten und etwas in diesem dunklen Abgrund bewirken könnten.\n\nSie lagen leider falsch. Den Schlund zu betreten bedeutet ewige Verdammnis.\n\nAber nicht für Euch.\n\nBitte findet heraus, was ihnen zugestoßen ist. Wenn Ihr sie findet, könnten ihre Seelen vielleicht wieder frei sein.", sourceObjective = "Findet kyrianische Aspiranten im Schlund und kehrt mit ihren Seelen zur Elysischen Feste zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[57508] = { id = 57508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsbanner der Zara'thik" }
quests[57510] = { id = 57510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkellord Taraxis" }
quests[57511] = { id = 57511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen für die Armen", description = "Dieser Graben ist mit den Überresten zahlloser Angriffe auf den Sitz des Primus übersät. Sie stammen von Streitkräften, die die Schattenlande bedrohten.\n\nJedes Mal trug Maldraxxus den Sieg davon.\n\nJetzt durchwühlen Plünderer alles in der Hoffnung, sich in eines der drei verbleibenden Häuser einkaufen zu können. In solch verzweifelten Zeiten müssen wir uns jeden möglichen Vorteil über unsere Rivalen sichern.\n\nWenn wir die Plünderer bewaffnen und ihnen eine zweite Chance auf Ruhm bieten, können wir die Reihen der Auserwählten auffüllen.", sourceObjective = "Bewaffnet 8 vertriebene Plünderer mit verstreuten Waffen aus dem Eisengraben.", completion = "Und jetzt prüfen wir sie.", sourceObjectiveStatus = "unverified-source-field" }
quests[57512] = { id = 57512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter dem Tod wandeln", description = "Durch diesen Graben hallen nekromantische Energien unzähliger ausgefochtener Kämpfe. Diese Macht hat sich zu chaotischen Wesen verbunden, die wir als Todeswandler bezeichnen.\n\nIn einfacheren Zeiten hätten wir Truppen entsandt, um sie zu unterwerfen, damit sie dem Haus der Auserwählten dienen. Aber durch den aufkommenden Krieg haben wir dafür keine Zeit.\n\nEliminiert die potenzielle Gefahr, bevor unser Gegner sie gegen uns richtet.", sourceObjective = "Tötet 8 ungebundene Todeswandler.", completion = "Alles in diesem Land ist gefährlich. Wir dürfen uns keine Schwäche erlauben.", sourceObjectiveStatus = "unverified-source-field" }
quests[57513] = { id = 57513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feind meines Feindes", description = "Zweifelsohne habt Ihr Fragen. Ihr sollt wissen, dass wir gemeinsame Feinde in diesem Land haben.\n\nDoch zunächst müssen wir los. Ich bringe Euch zu einem sichereren Ort, und dann können wir reden.", sourceObjective = "Entkommt aus dem Theater der Schmerzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57514] = { id = 57514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die erste Kriegshandlung", sourceObjective = "Meldet Euch bei Baron Vyraz.", completion = "Merkt Euch meine Worte, Rekrut. Für ihren Verrat werden wir die anderen Häuser niederreißen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57515] = { id = 57515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Haus der Auserwählten", description = "<Draka zeigt auf den Himmel.>\n\nSeht, <Sterblicher/Sterbliche>. Das ist die Nekropole des Markgrafen Krexus, der das Haus der Auserwählten führt. Es ist mir eine Ehre, ihm als Baronin zu dienen.\n\nLasst uns zu unserer Festung reiten. Dort können wir unsere Kräfte sammeln und uns auf die anstehende Schlacht vorbereiten.", sourceObjective = "Kehrt mit Draka zum Haus der Auserwählten zurück.", completion = "Die Auserwählten sind das Einzige, was von all dem übrig geblieben ist, wofür der Primus stand.\n\nWir sind die letzte Hoffnung dieses Reiches.", sourceObjectiveStatus = "unverified-source-field" }
quests[57516] = { id = 57516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch das Feuer und die Flammen", description = "Markgraf Krexus war erfreut über Eure Dienste für unser Haus. Er fühlt großes Potenzial in Euch.\n\nPotenzial, das geprüft werden muss.\n\nEin Stein steht im Zentrum unserer Zitadelle, umrundet von Magma. Den Stein zu erreichen ist eine Herausforderung für Ausdauer und Durchhaltevermögen.\n\nDiese Prüfung wagen üblicherweise nur unsere angesehensten Soldaten, doch Markgraf Krexus befiehlt Euch, den Ritus unmittelbar zu versuchen.\n\nNun denn, erweist Euch als würdig.", sourceObjective = "Erreicht den Menhir.", progress = "Was ist passiert?", completion = "Diese Klinge war die ganze Zeit in dem Stein... \n\nMarkgraf Krexus hatte Recht, was Euer Potenzial angeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[57517] = { id = 57517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarmrufer" }
quests[57519] = { id = 57519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarmrufer" }
quests[57521] = { id = 57521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkter Kriegswagen" }
quests[57522] = { id = 57522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Leere" }
quests[57524] = { id = 57524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archivzugriff", description = "Die von Euch gesammelten Informationen haben es uns ermöglicht, diese Manifestationen besser zu verstehen.\n\nIch glaube, MUTTER wartet darauf, einige ihrer Erkenntnisse mit Euch zu teilen.", sourceObjective = "Sprecht mit MUTTER, um das Titanenforschungsarchiv zu aktivieren, und untersucht danach die Archive.", progress = "Benötigt Ihr Unterstützung?", completion = "Archivdatenbank jetzt verfügbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[57529] = { id = 57529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufruhr im Garten", description = "Entschuldigt, dass ich nicht aufstehe. Ich möchte diese Wesen nur ungern stören.\n\nWenn Ihr den Kreaturen der Bastion helfen wollt, dann könnte Zosime Unterstützung im Garten brauchen. Ihr findet sie ein Stück weiter diesen Pfad entlang.\n\nGeht und dient.", sourceObjective = "Sprecht mit Zosime im Garten der Erholung.", completion = "Oh, seid Ihr hier, um mir zu helfen? Sehr schön!", sourceObjectiveStatus = "unverified-source-field" }
quests[57530] = { id = 57530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gharmals Turm", description = "Gharmal hat alle Gegenstände gesammelt, von denen er glaubte, dass sie Macht innehaben.\n\nWir werden den Turm durchsuchen müssen. Es ist nahezu sicher, dass wir hier etwas von Wert finden.", sourceObjective = "Durchsucht Gharmals Turm.", completion = "Da ist ganz sicher was. Machen wir es auf und sehen nach.", sourceObjectiveStatus = "unverified-source-field" }
quests[57531] = { id = 57531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine missliche Lage", description = "Laurent, Spiegelmacher des Meisters. Erfreut, Eure Bekanntschaft zu machen. Entschuldigt meine ungepflegte Erscheinung. Wie es scheint, bin ich in eine höchst misslichen Lage geraten.\n\nIch habe eine Reise in Angelegenheiten des Königreichs angetreten, doch mein Spiegel hat mich stattdessen in dieses Niemandsland gebracht.\n\nKurz nach meiner Ankunft hat mir eine Bande aus Verbannten die Kleider vom Leib gerissen und es mir unmöglich gemacht, dieses unwirtliche Terrain zu durchqueren.\n\nHelft mir, dann werde ich mich bemühen, einen Spiegel herzustellen, der es uns erlaubt, diesen elenden Ort zu verlassen.", sourceObjective = "Besiegt Costel und beschafft Laurents Habseligkeiten wieder.", progress = "Habt Ihr meine Habseligkeiten wiederbeschafft?", completion = "Ist das alles? Seid Ihr sicher, dass da nicht noch mehr war?", sourceObjectiveStatus = "unverified-source-field" }
quests[57532] = { id = 57532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragmente finden", description = "Verzeiht mir. Ich möchte nicht undankbar erscheinen, aber meine Spiegelfragmente fehlen.\n\nDas sollte mich eigentlich nicht überraschen. Sie sind ziemlich mächtig und ich bin sicher, dass die Schufte hier draußen sie nur zu gerne in die Finger bekämen.\n\nDennoch werde ich mich davon nicht abschrecken lassen.\n\nDer Meister schickt seine steinernen Dienern, um alle Spiegel, die in diesem Viertel aufgestellt wurden, zu zertrümmern. Also sollten wir keine Schwierigkeiten haben, Fragmente in der Nähe zu finden.", sourceObjective = "Folgt Laurent und sammelt Spiegelfragmente.", progress = "Simone hat hier nichts zu suchen!", completion = "Das muss ein Irrtum sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[57533] = { id = 57533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strafe des Lichts", description = "Die Gründe, weshalb man uns hierher verbannt hat, sind unterschiedlich, aber unser Ziel bei der Ankunft ist dasselbe: Wir wollen vermeiden, zu Asche zu werden.\n\nDie Verhüllten kontrollieren die vor dem Licht geschützten Bereiche. Wer unbefugt in ihre Hochburg eindringt, wird dafür büßen. Unser Fleisch schlägt Blasen und verbrennt und doch sterben wir nicht. Stattdessen wird unser Geist durch den Schmerz in die Tiefen des Wahnsinns hinabgezogen.\n\nIch behaupte nicht, die Verbrechen derjenigen zu kennen, die im Licht gefangen sind, aber ich weiß, dass dies nicht der Schlund ist. Es steht uns nicht zu, zu bestrafen.\n\nBefreit die anderen, so wie Ihr mich befreit habt.", sourceObjective = "Befreit 5 verbrennende Ausgestoßene.", completion = "Ihr habt sie befreit, ja? Dann hoffen wir, dass sie dort etwas Zuflucht gefunden haben, wo das Licht nicht hinscheint.", sourceObjectiveStatus = "unverified-source-field" }
quests[57534] = { id = 57534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn nur Asche bleibt", description = "Ist das hier wirklich das, was aus den Verbannten wird? Sie werden hier zurückgelassen, um zu Asche zu verbrennen?\n\nWie konnte der Meister so etwas zulassen? Das ist grausam, wenn nicht sogar herzlos.\n\nKein Venthyr würde so weiterleben wollen.\n\nIhr müsst ihrem Leiden ein Ende setzen.", sourceObjective = "Tötet 10 aschene Verheerer.", completion = "Ich hatte geglaubt, unseren Grafen zu kennen, aber jeder, der seinen Untergebenen so etwas antut, ist nicht würdig, dass man ihm folgt.", sourceObjectiveStatus = "unverified-source-field" }
